    [ -n "$role" ] && [ -z "$extra" ] || return 1
    nxbootstrap_component_target "$role" "$path" || return 1
    nxbootstrap_root_targets+=("$NXBOOTSTRAP_COMPONENT_TARGET_ROOT/$NXBOOTSTRAP_COMPONENT_TARGET_RELATIVE")
  done < "$generation_root/components.v2"
  nxbootstrap_batch_sha256 "${nxbootstrap_root_targets[@]}" || return 1
  while IFS=$'\t' read -r role mode expected path extra; do
    [ -n "$role" ] && [ -z "$extra" ] || return 1
    nxbootstrap_component_target "$role" "$path" || return 1
    target="$NXBOOTSTRAP_COMPONENT_TARGET_ROOT/$NXBOOTSTRAP_COMPONENT_TARGET_RELATIVE"
    nxbootstrap_real_file_below "$NXBOOTSTRAP_COMPONENT_TARGET_ROOT" \
      "$NXBOOTSTRAP_COMPONENT_TARGET_RELATIVE" || return 1
    nxbootstrap_file_mode_matches "$target" "$mode" || return 1
    check=${NXBOOTSTRAP_BATCH_SHA["$target"]:-}
    [ -n "$check" ] || return 1
    [ "$check" = "$expected" ] || return 1
