  # and the next launch deterministically completes the same immutable closure.
  for ((index=0; index<${#staged[@]}; index++)); do
    if ! mv -f -- "${staged[index]}" "${targets[index]}" 2>/dev/null; then
      for target in "${staged[@]}"; do rm -f -- "$target" 2>/dev/null || true; done
      return 1
    fi
    if ! nxbootstrap_real_file_below "${target_roots[index]}" \
         "${target_relatives[index]}" || \
       ! nxbootstrap_file_mode_matches "${targets[index]}" \
         "${expected_modes[index]}"; then
      for target in "${staged[@]}"; do rm -f -- "$target" 2>/dev/null || true; done
      return 1
    fi
    target=$(sha256sum "${targets[index]}" 2>/dev/null) || {
      for target in "${staged[@]}"; do rm -f -- "$target" 2>/dev/null || true; done
      return 1
    }
    if [ "${target%% *}" != "${expected_hashes[index]}" ]; then
      for target in "${staged[@]}"; do rm -f -- "$target" 2>/dev/null || true; done
      return 1
    fi
  done
  # No best-effort hybrid is allowed: every root member is re-read after all
  # renames and must match the same immutable generation before preflight.
  nxbootstrap_generation_v2_root_matches "$generation_root"
}
nxbootstrap_generation_v1_heal() {
  local generation_root=$1 line expected relpath source target_root target_rel mode
  local actual temporary check
  command -v sha256sum >/dev/null 2>&1 || return 0
  while IFS= read -r line; do
    expected=${line%%  *}
    relpath=${line#*  }
    case "$relpath" in
      launcher/*)
        target_root=$NXBOOTSTRAP_LAUNCHER_DIR
        target_rel=${relpath#launcher/}
        mode=0755 ;;
      nxport.json)
        target_root=$GAMEDIR target_rel=nxport.json mode=0644 ;;
      *) return 1 ;;
    esac
    source="$generation_root/files/$relpath"
    nxbootstrap_prepare_target_parent "$target_root" "$target_rel" || return 1
    nxbootstrap_heal_one "$source" "$target_root" "$target_rel" \
      "$expected" "$mode" "$relpath" || return 1
  done < "$generation_root/components.sha256"
}
# --- V4-REPACK-01 --------------------------------------------------------------
# The visible seed. A personal ZIP made by any archiver may legitimately drop
# every dotfile/dotdir, so `.nxruntime` is only a LOCAL CACHE. The authority is
# the regular, content-addressed file `nxruntime-<generation>.nxb` sitting next
# to nxport.json. Trust root: this launcher's baked generation id. The bundle
# carries identity.json, whose SHA-256 must equal that id; identity.json in turn
# pins nxport, every runtime member and the launcher preimage. Nothing here
# claims resistance against a local administrator able to replace launcher and
# bundle together - that is stated in BUNDLE-TRUST-V4.md, not hidden.
NXBOOTSTRAP_BUNDLE_NAME="nxruntime-$NXBOOTSTRAP_GENERATION_ID.nxb"
NXBOOTSTRAP_BUNDLE_MARGIN_BYTES=8388608
nxbootstrap_bundle_available_bytes() {
  # `df` is a coreutils/BusyBox builtin-grade tool present on every CFW we
  # target; the banned dependency is the external `stat`, never used here.
  local directory=$1 line value
  line=$(LC_ALL=C df -kP -- "$directory" 2>/dev/null | sed -n '2p') || return 1
  [ -n "$line" ] || return 1
  # shellcheck disable=SC2086
  set -- $line
  [ "$#" -ge 4 ] || return 1
  value=$4
  case "$value" in ''|*[!0-9]*) return 1 ;; esac
  printf '%s\n' "$((value * 1024))"
}
nxbootstrap_bundle_tree_bytes() {
  local root=$1 total
  [ -d "$root" ] && [ ! -L "$root" ] || { printf '0\n'; return 0; }
  total=$(LC_ALL=C du -sk -- "$root" 2>/dev/null | cut -f1) || total=""
  case "$total" in ''|*[!0-9]*) total=0 ;; esac
  printf '%s\n' "$((total * 1024))"
}
nxbootstrap_bundle_storage_preflight() {
  # V3-STORAGE-01 carried into V4: the honest cost of one materialization is
  # staging + the generation it becomes, while active/pending/previous stay in
  # place until a health receipt promotes the new one.
  local payload_bytes=$1 available required active pending previous
  available=$(nxbootstrap_bundle_available_bytes "$NXRUNTIME_DIR") || return 0
  active=$(nxbootstrap_bundle_tree_bytes \
    "$NXRUNTIME_DIR/generations/$(nxbootstrap_state_field active)")
  pending=$(nxbootstrap_bundle_tree_bytes \
    "$NXRUNTIME_DIR/generations/$(nxbootstrap_state_field pending)")
  previous=$(nxbootstrap_bundle_tree_bytes \
    "$NXRUNTIME_DIR/generations/$(nxbootstrap_state_field previous_healthy)")
  required=$((payload_bytes + NXBOOTSTRAP_BUNDLE_MARGIN_BYTES))
  echo "STORAGE: bundle=$payload_bytes active=$active pending=$pending previous=$previous required=$required available=$available"
  if [ "$available" -lt "$required" ]; then
    nxbootstrap_update_event NXU0013 "insufficient space to materialize the runtime: required=$required available=$available"
    return 1
  fi
  return 0
}
nxbootstrap_bundle_extract_member() {
  local bundle=$1 header_bytes=$2 offset=$3 size=$4 target=$5
  local start=$((header_bytes + offset + 1))
  if [ "$size" -eq 0 ]; then
    : > "$target" || return 1
    return 0
  fi
  tail -c "+$start" -- "$bundle" 2>/dev/null | head -c "$size" > "$target" \
    || return 1
}
nxbootstrap_bundle_materialize() {
  # Rebuild the local cache from the seed. All-or-nothing: staging is private,
  # every member is verified against the header, the whole tree is then
  # authenticated by the SAME closed validator used for an installed
  # generation, `commit` is written last and only then is the tree promoted by
  # one atomic rename.
  local bundle=$1 staging_root staging generation_root
  local magic line kind mode digest size offset path extra
  local nxbootstrap_bundle_paths=""
  local member_count=0 declared=0 header_lines=0 header_bytes payload_total=0
  local expect_offset=0 target actual launcher_recorded launcher_actual
  local bundle_generation=""
  command -v sha256sum >/dev/null 2>&1 || {
    nxbootstrap_update_event NXU0012 "sha256sum is unavailable; the runtime seed cannot be authenticated"
    return 1
  }
  [ -f "$bundle" ] && [ ! -L "$bundle" ] || {
    nxbootstrap_update_event NXU0012 "runtime seed $NXBOOTSTRAP_BUNDLE_NAME is absent or not a regular file"
    return 1
  }
  IFS= read -r magic < "$bundle" || magic=""
  [ "$magic" = NXBUNDLE1 ] || {
    nxbootstrap_update_event NXU0012 "runtime seed header is not nxbundle-v1"
    return 1
  }
  # Parse the ASCII header. Any malformed line fails closed before any write.
  while IFS= read -r line; do
    header_lines=$((header_lines + 1))
    [ "$header_lines" -le 4096 ] || return 1
    case "$header_lines" in
      1) [ "$line" = NXBUNDLE1 ] || return 1 ; continue ;;
    esac
    case "$line" in
      "generation "*)
        bundle_generation=${line#generation }
        [ "$bundle_generation" = "$NXBOOTSTRAP_GENERATION_ID" ] || {
          nxbootstrap_update_event NXU0012 "runtime seed declares generation $bundle_generation; launcher carries $NXBOOTSTRAP_GENERATION_ID"
          return 1
        }
        continue ;;
      "port "*) continue ;;
      "members "*)
        declared=${line#members }
        case "$declared" in ''|*[!0-9]*) return 1 ;; esac
        [ "$declared" -ge 1 ] && [ "$declared" -le 4096 ] || return 1
        continue ;;
      END) break ;;
      "M	"*) ;;
      *) return 1 ;;
    esac
    IFS=$'\t' read -r kind mode digest size offset path extra <<< "$line"
    [ "$kind" = M ] && [ -z "$extra" ] || return 1
    case "$mode" in 0644|0755) ;; *) return 1 ;; esac
    [ "${#digest}" -eq 64 ] || return 1
    case "$digest" in *[!0-9a-f]*) return 1 ;; esac
    case "$size" in ''|*[!0-9]*) return 1 ;; esac
    case "$offset" in ''|*[!0-9]*) return 1 ;; esac
    [ "$offset" -eq "$expect_offset" ] || return 1
    nxbootstrap_relative_path_safe "$path" || return 1
    case "$path" in commit|*/commit) return 1 ;; esac
    expect_offset=$((expect_offset + size))
    member_count=$((member_count + 1))
    [ "$member_count" -le 4096 ] || return 1
    nxbootstrap_bundle_paths="$nxbootstrap_bundle_paths$path
"
  done < "$bundle"
  [ "$line" = END ] || return 1
  # The media this runs on is case-insensitive: /roms is exFAT. Two members
  # differing only in case are distinct in the header and the SAME file on the
  # card, so one silently overwrites the other and the closure that gets
  # verified is not the closure that was declared. Refuse the ambiguity here,
  # where it can still be named, instead of letting it surface as a hash
  # mismatch on an unrelated member. One pipeline for the whole header.
  if [ -n "$nxbootstrap_bundle_paths" ] &&
     printf '%s' "$nxbootstrap_bundle_paths" | tr 'A-Z' 'a-z' |
       LC_ALL=C sort | uniq -d | grep -q .; then
    nxbootstrap_update_event NXU0012 \
      "runtime seed members collide on case-insensitive media"
    return 1
  fi
  [ -n "$bundle_generation" ] && [ "$member_count" -eq "$declared" ] || return 1
  payload_total=$expect_offset
  header_bytes=$(head -n "$header_lines" -- "$bundle" | wc -c) || return 1
  case "$header_bytes" in ''|*[!0-9]*) return 1 ;; esac
  [ -d "$NXRUNTIME_DIR" ] || ( umask 077; mkdir -p "$NXRUNTIME_DIR" ) 2>/dev/null || return 1
  [ -d "$NXRUNTIME_DIR" ] && [ ! -L "$NXRUNTIME_DIR" ] || return 1
  nxbootstrap_bundle_storage_preflight "$payload_total" || return 1
  staging_root="$NXRUNTIME_DIR/staging.$$.${RANDOM}${RANDOM}"
  rm -rf -- "$staging_root" 2>/dev/null || true
  ( umask 077; mkdir -- "$staging_root" ) 2>/dev/null || return 1
  staging="$staging_root/$NXBOOTSTRAP_GENERATION_ID"
  mkdir -- "$staging" 2>/dev/null || { rm -rf -- "$staging_root"; return 1; }
  while IFS=$'\t' read -r kind mode digest size offset path extra; do
    [ "$kind" = M ] || continue
    nxbootstrap_prepare_target_parent "$staging" "$path" || {
      rm -rf -- "$staging_root" 2>/dev/null || true
      return 1
    }
    target="$staging/$path"
    [ ! -e "$target" ] && [ ! -L "$target" ] || {
      rm -rf -- "$staging_root" 2>/dev/null || true
      return 1
    }
    if ! ( umask 077; nxbootstrap_bundle_extract_member \
             "$bundle" "$header_bytes" "$offset" "$size" "$target" ); then
      nxbootstrap_update_event NXU0012 "runtime seed is truncated at $path"
      rm -rf -- "$staging_root" 2>/dev/null || true
      return 1
    fi
    actual=$(sha256sum "$target" 2>/dev/null) || {
      rm -rf -- "$staging_root" 2>/dev/null || true
      return 1
    }
    if [ "${actual%% *}" != "$digest" ]; then
      nxbootstrap_update_event NXU0012 "runtime seed member $path failed authentication"
      rm -rf -- "$staging_root" 2>/dev/null || true
      return 1
    fi
    chmod "${mode#0}" -- "$target" 2>/dev/null || true
    # Re-read ONLY the header. `sed -n "5,Np"` would stream the entire seed --
    # payload included -- through sed on every rebuild: hundreds of megabytes
    # off the card for nothing, and sed over binary with embedded NUL bytes is
    # implementation-defined on a BusyBox CFW. head stops at the line bound.
  done < <(head -n "$((header_lines - 1))" -- "$bundle" | tail -n +5)
  # The seed never carries `commit`; it is written last, on the device, as the
  # local receipt that the closure arrived complete.
  if ! nxbootstrap_generation_v2_complete "$staging"; then
    nxbootstrap_update_event NXU0012 "materialized closure did not authenticate"
    rm -rf -- "$staging_root" 2>/dev/null || true
    return 1
  fi
  # The closure itself is verified byte-for-byte against components.v2 above.
  # What is compared HERE is a different relation: the launcher the frontend
  # installed against the launcher the closure carries. PortMaster owns line 2
  # of an installed launcher and rewrites it with the name of the zip it
  # installed from, so that one comment line is normalized on BOTH sides
  # before comparing. Nothing in the manifest changes and no recorded hash is
  # weakened: the closure's own integrity is untouched.
  launcher_recorded=$(nxbootstrap_launcher_canonical_sha256 \
    "$staging/files/launcher/Riptide GP1.sh") || launcher_recorded=""
  launcher_actual=$(nxbootstrap_launcher_canonical_sha256 \
    "$NXBOOTSTRAP_LAUNCHER_DIR/Riptide GP1.sh") || launcher_actual=""
  if [ -z "$launcher_recorded" ] || [ "$launcher_recorded" != "$launcher_actual" ]; then
    nxbootstrap_update_event NXU0012 "installed launcher does not match the runtime seed closure"
    rm -rf -- "$staging_root" 2>/dev/null || true
    return 1
  fi
  if ! ( umask 022; printf '%s\n' "$NXBOOTSTRAP_GENERATION_ID" \
           > "$staging/commit" ); then
    rm -rf -- "$staging_root" 2>/dev/null || true
    return 1
  fi
  chmod 0644 -- "$staging/commit" 2>/dev/null || true
  mkdir -p -- "$NXRUNTIME_DIR/generations" 2>/dev/null || {
    rm -rf -- "$staging_root" 2>/dev/null || true
    return 1
  }
  generation_root="$NXRUNTIME_DIR/generations/$NXBOOTSTRAP_GENERATION_ID"
  if [ -e "$generation_root" ] || [ -L "$generation_root" ]; then
    # Another launch won the race, or a partial tree is present. Never repair a
    # generation in place; leave the existing one to the normal validators.
    rm -rf -- "$staging_root" 2>/dev/null || true
    nxbootstrap_generation_selectable "$generation_root"
    return $?
  fi
  if ! mv -- "$staging" "$generation_root" 2>/dev/null; then
    rm -rf -- "$staging_root" 2>/dev/null || true
    return 1
  fi
  rm -rf -- "$staging_root" 2>/dev/null || true
  nxbootstrap_update_event NXU0012 "runtime cache rebuilt from seed $NXBOOTSTRAP_BUNDLE_NAME (generation $NXBOOTSTRAP_GENERATION_ID)"
  nxbootstrap_generation_selectable "$generation_root"
}
# The cache is rebuilt ONLY when this launcher's own generation directory is
# absent. An existing directory - complete, truncated or tampered - is left
# exactly as it is for the normal validators: a generation is never repaired
# in place and a missing `commit` is never manufactured by healing.
if [ "$NXBOOTSTRAP_GENERATION_FORMAT" = 2 ] && \
   [ -n "$NXBOOTSTRAP_GENERATION_ID" ] && \
   [ ! -e "$NXRUNTIME_DIR/generations/$NXBOOTSTRAP_GENERATION_ID" ] && \
   [ ! -L "$NXRUNTIME_DIR/generations/$NXBOOTSTRAP_GENERATION_ID" ] && \
   { [ -e "$GAMEDIR/$NXBOOTSTRAP_BUNDLE_NAME" ] || \
     [ -L "$GAMEDIR/$NXBOOTSTRAP_BUNDLE_NAME" ]; }; then
  nxbootstrap_bundle_materialize "$GAMEDIR/$NXBOOTSTRAP_BUNDLE_NAME" || true
fi

# RGP-SELFHEAL-01: cópia parcial (transferência interrompida, dotfiles
# perdidos) deixa o próprio diretório de geração presente porém incompleto —
# e o materialize acima só roda quando ele está AUSENTE. Sem isto, todo boot
# cai em "no complete generation-v2 closure found; launch refused" para
# sempre. Reparo seguro: só o own-generation, só quando INCOMPLETO, só a
# partir do seed autenticado (o materialize valida tudo antes de promover;
# nada é reparado "in place", e generation saudável nunca é tocada).
if [ "$NXBOOTSTRAP_GENERATION_FORMAT" = 2 ] && \
   [ -n "$NXBOOTSTRAP_GENERATION_ID" ] && \
   { [ -e "$NXRUNTIME_DIR/generations/$NXBOOTSTRAP_GENERATION_ID" ] || \
     [ -L "$NXRUNTIME_DIR/generations/$NXBOOTSTRAP_GENERATION_ID" ]; } && \
   ! nxbootstrap_generation_selectable "$NXRUNTIME_DIR/generations/$NXBOOTSTRAP_GENERATION_ID" && \
   [ -f "$GAMEDIR/$NXBOOTSTRAP_BUNDLE_NAME" ] && \
   [ ! -L "$GAMEDIR/$NXBOOTSTRAP_BUNDLE_NAME" ]; then
  echo "RGP-SELFHEAL: own generation present but incomplete; rebuilding from seed bundle"
  rm -rf -- "$NXRUNTIME_DIR/generations/$NXBOOTSTRAP_GENERATION_ID" 2>/dev/null || true
  nxbootstrap_bundle_materialize "$GAMEDIR/$NXBOOTSTRAP_BUNDLE_NAME" || true
fi
NXBOOTSTRAP_SELECTED_GENERATION=""
if [ -d "$NXRUNTIME_DIR/generations" ]; then
  nxbootstrap_state_active=$(nxbootstrap_state_field active)
  nxbootstrap_state_pending=$(nxbootstrap_state_field pending)
  nxbootstrap_state_previous=$(nxbootstrap_state_field previous_healthy)
  nxbootstrap_state_seq=$(nxbootstrap_state_field activation_seq)
  nxbootstrap_state_failures=$(nxbootstrap_state_field prehealth_failures)
  nxbootstrap_state_failure_generation=$(nxbootstrap_state_field failure_generation)
  nxbootstrap_state_last_health_run=$(nxbootstrap_state_field last_health_run_id)
  case "$nxbootstrap_state_seq" in ''|*[!0-9]*) nxbootstrap_state_seq=0 ;; esac
  case "$nxbootstrap_state_failures" in ''|*[!0-9]*) nxbootstrap_state_failures=0 ;; esac
  nxbootstrap_generation_id_valid "$nxbootstrap_state_active" || nxbootstrap_state_active=null
  nxbootstrap_generation_id_valid "$nxbootstrap_state_pending" || nxbootstrap_state_pending=null
  nxbootstrap_generation_id_valid "$nxbootstrap_state_previous" || nxbootstrap_state_previous=null
  nxbootstrap_generation_id_valid "$nxbootstrap_state_failure_generation" || nxbootstrap_state_failure_generation=null
  # Crash-loop guard is tied to one PENDING generation. A stable active
  # generation is never demoted because an unrelated run happened to fail.
  if [ "$nxbootstrap_state_failures" -ge 3 ] && \
     [ "$nxbootstrap_state_pending" != null ] && \
     [ "$nxbootstrap_state_failure_generation" = "$nxbootstrap_state_pending" ]; then
    # Once the retry budget is exhausted, the pending generation is no longer
    # a launch candidate.  Missing/corrupt/incompatible rollback state must not
    # turn the guard into an unbounded fourth, fifth, ... health trial.
    if [ -n "$nxbootstrap_state_previous" ] && \
       [ "$nxbootstrap_state_previous" != "null" ] && \
       nxbootstrap_generation_selectable "$NXRUNTIME_DIR/generations/$nxbootstrap_state_previous" && \
       { ! nxbootstrap_generation_is_v2 "$NXRUNTIME_DIR/generations/$nxbootstrap_state_pending" || \
         nxbootstrap_generation_is_v2 "$NXRUNTIME_DIR/generations/$nxbootstrap_state_previous"; }; then
      NXBOOTSTRAP_SELECTED_GENERATION=$nxbootstrap_state_previous
      if nxbootstrap_write_state "$nxbootstrap_state_previous" "null" \
        "$nxbootstrap_state_previous" "$nxbootstrap_state_seq" 0 "null" \
        "${nxbootstrap_state_last_health_run:-null}"; then
        nxbootstrap_update_event NXU0004 "crash-loop: previous healthy generation $nxbootstrap_state_previous selected"
      else
        nxbootstrap_update_event NXU0011 "rollback state could not be persisted; refusing a hybrid launch"
        nxbootstrap_finish
        exit 1
      fi
      nxbootstrap_state_active=$nxbootstrap_state_previous
      nxbootstrap_state_pending=null
      nxbootstrap_state_failures=0
      nxbootstrap_state_failure_generation=null
    elif [ "$nxbootstrap_state_active" = null ] && \
         [ "$nxbootstrap_state_previous" = null ] && \
         nxbootstrap_generation_selectable \
           "$NXRUNTIME_DIR/generations/$nxbootstrap_state_pending"; then
      # A fresh install has no older bytes to roll back to. Refusing its only
      # complete runtime cannot recover anything and permanently bricks the
      # port. Retry that exact authenticated generation in degraded mode; a
      # later clean first exit or exact receipt promotes it normally. Real
      # updates that DO have a healthy anchor keep the strict rollback above.
      NXBOOTSTRAP_SELECTED_GENERATION=$nxbootstrap_state_pending
      nxbootstrap_state_failures=0
      if nxbootstrap_write_state "null" "$nxbootstrap_state_pending" "null" \
        "$nxbootstrap_state_seq" 0 "$nxbootstrap_state_pending" \
        "${nxbootstrap_state_last_health_run:-null}"; then
        nxbootstrap_update_event NXU0015 "fresh install has no rollback anchor; retrying its only complete generation instead of refusing launch"
      else
        nxbootstrap_update_event NXU0011 "fresh-install retry state could not be persisted; launching the only complete generation without fabricating an anchor"
      fi
    else
      nxbootstrap_update_event NXU0009 "crash-loop rollback anchor is absent, incomplete or incompatible; launch refused; run nxdoctor"
      nxbootstrap_finish
      exit 1
    fi
  elif [ -n "$NXBOOTSTRAP_GENERATION_ID" ] && \
       [ "$nxbootstrap_state_failures" -eq 0 ] && \
       [ ! -e "$NXRUNTIME_DIR/deep-verify-next" ] && \
       [ ! -L "$NXRUNTIME_DIR/deep-verify-next" ] && \
       { [ "$nxbootstrap_state_active" = "$NXBOOTSTRAP_GENERATION_ID" ] || \
         [ "$nxbootstrap_state_pending" = "$NXBOOTSTRAP_GENERATION_ID" ] || \
         { [ "$nxbootstrap_state_active" = null ] && \
           [ "$nxbootstrap_state_pending" = null ]; }; } && \
       nxbootstrap_generation_v2_fast_boot_ok "$NXRUNTIME_DIR/generations/$NXBOOTSTRAP_GENERATION_ID"; then
    # V4-BOOT-01 fast path: the persisted state (or a brand-new install with
    # no state yet) points at this launcher's own committed generation and
    # its first attempt is allowed to run; the run-bound health receipt still
    # decides promotion and any failure sends the next boot through the deep
    # path.
    NXBOOTSTRAP_SELECTED_GENERATION=$NXBOOTSTRAP_GENERATION_ID
    NXBOOTSTRAP_FAST_BOOT=1
  elif [ -n "$NXBOOTSTRAP_GENERATION_ID" ] && \
     nxbootstrap_generation_selectable "$NXRUNTIME_DIR/generations/$NXBOOTSTRAP_GENERATION_ID"; then
    NXBOOTSTRAP_SELECTED_GENERATION=$NXBOOTSTRAP_GENERATION_ID
  elif [ "$nxbootstrap_state_pending" != null ] && \
       nxbootstrap_generation_selectable "$NXRUNTIME_DIR/generations/$nxbootstrap_state_pending"; then
    NXBOOTSTRAP_SELECTED_GENERATION=$nxbootstrap_state_pending
    nxbootstrap_update_event NXU0008 "pending generation $nxbootstrap_state_pending selected for health trial"
  elif [ -n "$nxbootstrap_state_active" ] && \
       [ "$nxbootstrap_state_active" != "null" ] && \
       nxbootstrap_generation_selectable "$NXRUNTIME_DIR/generations/$nxbootstrap_state_active"; then
    NXBOOTSTRAP_SELECTED_GENERATION=$nxbootstrap_state_active
    nxbootstrap_update_event NXU0002 "own generation $NXBOOTSTRAP_GENERATION_ID incomplete; running last good $nxbootstrap_state_active"
  else
    for nxbootstrap_candidate in "$NXRUNTIME_DIR/generations"/*/; do
      [ -d "$nxbootstrap_candidate" ] || continue
      nxbootstrap_candidate=${nxbootstrap_candidate%/}
      if nxbootstrap_generation_selectable "$nxbootstrap_candidate"; then
        NXBOOTSTRAP_SELECTED_GENERATION=${nxbootstrap_candidate##*/}
        nxbootstrap_update_event NXU0002 "no state; complete generation ${nxbootstrap_candidate##*/} selected"
        break
      fi
      nxbootstrap_update_event NXU0002 "generation ${nxbootstrap_candidate##*/} is truncated or stale; ignored (not deleted)"
    done
  fi
  if [ -n "$NXBOOTSTRAP_SELECTED_GENERATION" ]; then
    nxbootstrap_generation_root="$NXRUNTIME_DIR/generations/$NXBOOTSTRAP_SELECTED_GENERATION"
    if [ "$NXBOOTSTRAP_SELECTED_GENERATION" != "$NXBOOTSTRAP_GENERATION_ID" ]; then
      nxbootstrap_update_event NXU0001 "mixed installation: launcher carries $NXBOOTSTRAP_GENERATION_ID, runtime generation is $NXBOOTSTRAP_SELECTED_GENERATION"
    fi
    # Self-heal the whole selected closure. V2 is all-or-nothing and refuses
    # to start if any top-level member remains mixed after the atomic copies.
    if [ "${NXBOOTSTRAP_FAST_BOOT:-0}" = 1 ] && \
       nxbootstrap_generation_v2_clean_stale_heal_temps "$nxbootstrap_generation_root"; then
      # V4-BOOT-01: healthy committed boot -- no closure walk, no heal (the
      # dead-PID staging sweep above is builtin-only when nothing is stale).
      # Deep verification remains the path for every state/identity mismatch,
      # and a sweep refusal falls through to the full heal below.
      :
    elif nxbootstrap_generation_is_v2 "$nxbootstrap_generation_root"; then
      if ! nxbootstrap_generation_v2_heal "$nxbootstrap_generation_root"; then
        nxbootstrap_update_event NXU0009 "generation-v2 closure could not be healed and revalidated"
        nxbootstrap_finish
        exit 1
      fi
      # The deep pass just revalidated and healed the whole closure; the
      # one-shot deep-verify request (if any) is satisfied.
      rm -f -- "$NXRUNTIME_DIR/deep-verify-next" 2>/dev/null || true
    elif ! nxbootstrap_generation_v1_heal "$nxbootstrap_generation_root"; then
      nxbootstrap_update_event NXU0009 "legacy control generation could not be healed"
      nxbootstrap_finish
      exit 1
    fi
    # A rollback selected another launcher's exact code/config. Restart once
    # from the healed entry point so this shell cannot continue with the newer
    # baked executable path and create a hybrid runtime.
    if [ "$NXBOOTSTRAP_SELECTED_GENERATION" != "$NXBOOTSTRAP_GENERATION_ID" ] && \
       nxbootstrap_generation_is_v2 "$nxbootstrap_generation_root"; then
      if [ "${NXBOOTSTRAP_GENERATION_RESTARTED:-}" = "$NXBOOTSTRAP_SELECTED_GENERATION" ]; then
        nxbootstrap_update_event NXU0009 "generation restart loop detected"
        nxbootstrap_finish
        exit 1
      fi
      export NXBOOTSTRAP_GENERATION_RESTARTED=$NXBOOTSTRAP_SELECTED_GENERATION
      nxbootstrap_update_event NXU0010 "restarting from healed generation $NXBOOTSTRAP_SELECTED_GENERATION"
      exec "$NXBOOTSTRAP_LAUNCHER_DIR/Riptide GP1.sh" "$@"
      nxbootstrap_update_event NXU0009 "healed generation launcher could not restart"
      nxbootstrap_finish
      exit 1
    fi
    # A new generation stays PENDING. It does not replace active until an
    # exact, run-bound health receipt is validated after the child exits.
    if [ "$nxbootstrap_state_active" != "$NXBOOTSTRAP_SELECTED_GENERATION" ]; then
      if [ "$nxbootstrap_state_pending" != "$NXBOOTSTRAP_SELECTED_GENERATION" ]; then
        nxbootstrap_state_previous=null
        if nxbootstrap_generation_is_v2 "$nxbootstrap_generation_root" && \
           [ "$nxbootstrap_state_active" != null ] && \
           nxbootstrap_generation_is_v2 "$NXRUNTIME_DIR/generations/$nxbootstrap_state_active" && \
           nxbootstrap_generation_complete "$NXRUNTIME_DIR/generations/$nxbootstrap_state_active"; then
          nxbootstrap_state_previous=$nxbootstrap_state_active
        elif ! nxbootstrap_generation_is_v2 "$nxbootstrap_generation_root"; then
          nxbootstrap_state_previous=$nxbootstrap_state_active
          [ "$nxbootstrap_state_previous" != null ] || \
            nxbootstrap_state_previous=${nxbootstrap_state_previous:-null}
        fi
        nxbootstrap_state_seq=$((nxbootstrap_state_seq + 1))
        nxbootstrap_state_failures=0
      fi
      nxbootstrap_state_pending=$NXBOOTSTRAP_SELECTED_GENERATION
      nxbootstrap_state_failure_generation=$NXBOOTSTRAP_SELECTED_GENERATION
      if ! nxbootstrap_write_state "${nxbootstrap_state_active:-null}" \
        "$nxbootstrap_state_pending" "${nxbootstrap_state_previous:-null}" \
        "$nxbootstrap_state_seq" "$nxbootstrap_state_failures" \
        "$nxbootstrap_state_failure_generation" \
        "${nxbootstrap_state_last_health_run:-null}"; then
        if nxbootstrap_generation_is_v2 "$nxbootstrap_generation_root"; then
          nxbootstrap_update_event NXU0011 "pending generation state could not be persisted; launch refused"
          nxbootstrap_finish
          exit 1
        fi
      fi
    fi
  elif [ -n "$(ls -A "$NXRUNTIME_DIR/generations" 2>/dev/null)" ]; then
    if [ "$NXBOOTSTRAP_GENERATION_FORMAT" = 2 ]; then
      nxbootstrap_update_event NXU0009 "no complete generation-v2 closure found; launch refused"

      echo "RGP-DIAG: generations content:"
      ls -la -- "$NXRUNTIME_DIR/generations" 2>/dev/null || echo "RGP-DIAG: generations unreadable"
      for rgp_cand in "$NXRUNTIME_DIR/generations"/*/; do
        [ -d "$rgp_cand" ] || continue
        rgp_name=${rgp_cand%/}; rgp_name=${rgp_name##*/}
        rgp_commit=$(head -n 1 -- "$rgp_cand/commit" 2>/dev/null || echo UNREADABLE)
        rgp_id_actual=$(sha256sum -- "$rgp_cand/identity.json" 2>/dev/null); rgp_id_actual=${rgp_id_actual%% *}
        if [ "$rgp_id_actual" = "$rgp_name" ]; then rgp_id_ok=yes; else rgp_id_ok=no; fi
        echo "RGP-DIAG: gen=$rgp_name commit=$rgp_commit identity_match=$rgp_id_ok manifest=$([ -f "$rgp_cand/manifest.json" ] && echo yes || echo no)"
      done
      echo "RGP-DIAG: seed $NXBOOTSTRAP_BUNDLE_NAME present=$([ -f "$GAMEDIR/$NXBOOTSTRAP_BUNDLE_NAME" ] && echo yes || echo no)"
      df -h -- "$GAMEDIR" 2>/dev/null || df -- "$GAMEDIR" 2>/dev/null || true
      unset rgp_cand rgp_name rgp_commit rgp_id_actual rgp_id_ok
      nxbootstrap_finish
      exit 1
    fi
    nxbootstrap_update_event NXU0001 "no complete generation found; continuing with legacy installed control files"
  fi
fi
if [ "$NXBOOTSTRAP_GENERATION_FORMAT" = 2 ] && \
   [ -z "$NXBOOTSTRAP_SELECTED_GENERATION" ]; then
  nxbootstrap_update_event NXU0009 "generation-v2 closure is absent; launch refused"

      echo "RGP-DIAG: generations content:"
      ls -la -- "$NXRUNTIME_DIR/generations" 2>/dev/null || echo "RGP-DIAG: generations unreadable"
      for rgp_cand in "$NXRUNTIME_DIR/generations"/*/; do
        [ -d "$rgp_cand" ] || continue
        rgp_name=${rgp_cand%/}; rgp_name=${rgp_name##*/}
        rgp_commit=$(head -n 1 -- "$rgp_cand/commit" 2>/dev/null || echo UNREADABLE)
        rgp_id_actual=$(sha256sum -- "$rgp_cand/identity.json" 2>/dev/null); rgp_id_actual=${rgp_id_actual%% *}
        if [ "$rgp_id_actual" = "$rgp_name" ]; then rgp_id_ok=yes; else rgp_id_ok=no; fi
        echo "RGP-DIAG: gen=$rgp_name commit=$rgp_commit identity_match=$rgp_id_ok manifest=$([ -f "$rgp_cand/manifest.json" ] && echo yes || echo no)"
      done
      echo "RGP-DIAG: seed $NXBOOTSTRAP_BUNDLE_NAME present=$([ -f "$GAMEDIR/$NXBOOTSTRAP_BUNDLE_NAME" ] && echo yes || echo no)"
      df -h -- "$GAMEDIR" 2>/dev/null || df -- "$GAMEDIR" 2>/dev/null || true
      unset rgp_cand rgp_name rgp_commit rgp_id_actual rgp_id_ok
  nxbootstrap_finish
  exit 1
fi
# ------------------------------------------------------------------------------

nxbootstrap_validate_nxextract_result() {
  python3 -B - "$1" "$2" <<'PY'
import json
import os
import re
import stat
import sys

sys.tracebacklimit = 0
path, process_status_text = sys.argv[1:]
process_status = int(process_status_text)
# Members born WITH schema_version 1 are required. Members added LATER in the
# same schema_version (ui, and any future addition) are validated only when
# present -- BOTH directions of a partially updated install keep working:
# old launcher + new engine (extra member ignored there) and new launcher +
# old engine (missing member tolerated here).
top_keys = {
    "schema", "schema_version", "nxextract_version", "outcome", "code",
    "final_phase", "recipe", "package_id", "abi", "container",
    "validated", "logs", "duration_ms", "completed_unix", "error",
}
phase_ids = (
    "preparing", "scanning", "validating-packages", "selecting",
    "extracting", "processing", "validating-data", "installing", "ready",
)
sha256_re = re.compile(r"^[0-9a-f]{64}$")
safe_id_re = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$")

def reject(message):
    raise ValueError(message)

def pairs(items):
    result = {}
    for key, value in items:
        if key in result:
            reject("duplicate JSON member")
        result[key] = value
    return result

def finite_constant(_value):
    reject("non-finite JSON number")

def exact_object(value, keys, label):
    if not isinstance(value, dict) or set(value) != set(keys):
        reject("invalid " + label + " object")


def require_members(value, keys, label):
    # 0.6.26: FORWARD-COMPATIBLE. Every known member must be present and is
    # validated below, but EXTRA members added by a newer engine are ignored
    # instead of rejected -- adding a field is a compatible change. The real
    # compatibility contract is schema + schema_version, checked right after.
    if not isinstance(value, dict) or not set(keys) <= set(value):
        reject("invalid " + label + " object")

def integer(value, label):
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        reject("invalid " + label)

def string(value, minimum, maximum, label):
    if not isinstance(value, str) or not minimum <= len(value) <= maximum:
        reject("invalid " + label)
    if any(ord(char) < 32 for char in value):
        reject("control byte in " + label)

def relative_path(value, label):
    string(value, 1, 512, label)
    if value.startswith("/") or "\\" in value or ".." in value.split("/"):
        reject("invalid " + label)

flags = (os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) |
         getattr(os, "O_NOFOLLOW", 0))
fd = os.open(path, flags)
try:
    opened = os.fstat(fd)
    linked = os.lstat(path)
    if (not stat.S_ISREG(opened.st_mode) or opened.st_nlink != 1 or
            (opened.st_dev, opened.st_ino) != (linked.st_dev, linked.st_ino)):
        reject("unsafe result identity")
    chunks = []
    total = 0
    while True:
        block = os.read(fd, 65536)
        if not block:
            break
        total += len(block)
        if total > 1048576:
            reject("result exceeds size limit")
        chunks.append(block)
finally:
    os.close(fd)

document = json.loads(
    b"".join(chunks).decode("utf-8", "strict"),
    object_pairs_hook=pairs,
    parse_constant=finite_constant,
)
require_members(document, top_keys, "terminal result")
# The compatibility contract is the schema id + schema_version ONLY. A newer
# engine (any nxextract_version) that keeps schema_version 1 stays readable by
# this launcher -- so a partially-updated install (new engine under an older
# launcher .sh) no longer dies with "unknown terminal result schema". A real
# breaking change would bump schema_version, which this gate still rejects.
if (document["schema"] != "org.nextos.nxextract.terminal-result" or
        isinstance(document["schema_version"], bool) or
        document["schema_version"] != 1 or
        not isinstance(document["nxextract_version"], str) or
        re.fullmatch(r"[0-9]{1,4}\.[0-9]{1,4}\.[0-9]{1,4}",
                     document["nxextract_version"]) is None):
    reject("unknown terminal result schema")
if document["outcome"] not in ("success", "error"):
    reject("invalid terminal outcome")
if (process_status == 0) != (document["outcome"] == "success"):
    reject("process status and terminal outcome disagree")
if (not isinstance(document["code"], str) or
        not re.fullmatch(r"^NXE[0-9]{4}$", document["code"])):
    reject("invalid terminal code")

phase = document["final_phase"]
exact_object(phase, ("index", "id", "label"), "final phase")
integer(phase["index"], "phase index")
if phase["index"] > 8 or phase["id"] != phase_ids[phase["index"]]:
    reject("invalid final phase")
string(phase["label"], 1, 64, "phase label")

recipe = document["recipe"]
exact_object(recipe, ("id", "version", "digest"), "recipe")
if (not isinstance(recipe["id"], str) or
        not safe_id_re.fullmatch(recipe["id"])):
    reject("invalid recipe id")
string(recipe["version"], 1, 128, "recipe version")
if (not isinstance(recipe["digest"], str) or
        not sha256_re.fullmatch(recipe["digest"])):
    reject("invalid recipe digest")

if document["package_id"] is not None:
    string(document["package_id"], 1, 255, "package id")
abi = document["abi"]
if (abi is not None and
        (not isinstance(abi, str) or
         not re.fullmatch(r"^[A-Za-z0-9._-]{1,64}$", abi))):
    reject("invalid ABI")
container = document["container"]
exact_object(container, ("kind", "identity"), "container")
if container["kind"] not in (
        "apk-set", "bundle", "companion", "existing", None):
    reject("invalid container kind")
identity = container["identity"]
if (identity is not None and
        (not isinstance(identity, str) or not sha256_re.fullmatch(identity))):
    reject("invalid container identity")

validated = document["validated"]
exact_object(validated, ("items", "bytes", "critical_payloads"), "validated")
integer(validated["items"], "validated item count")
integer(validated["bytes"], "validated byte count")
critical = validated["critical_payloads"]
if not isinstance(critical, list) or len(critical) > 256:
    reject("invalid critical payload list")
for item in critical:
    exact_object(item, ("id", "items", "bytes"), "critical payload")
    if (not isinstance(item["id"], str) or
            not safe_id_re.fullmatch(item["id"])):
        reject("invalid critical payload id")
    integer(item["items"], "critical payload item count")
    integer(item["bytes"], "critical payload byte count")

logs = document["logs"]
exact_object(logs, ("summary", "detail"), "logs")
relative_path(logs["summary"], "summary log")
relative_path(logs["detail"], "detail log")
integer(document["duration_ms"], "duration")
integer(document["completed_unix"], "completion time")

if "ui" in document:
    ui = document["ui"]
    exact_object(ui, ("mode", "renderer", "fallback_reason"), "ui")
    if ui["mode"] not in ("visible", "headless-fallback", "disabled"):
        reject("invalid ui mode")
    if ui["renderer"] is not None:
        string(ui["renderer"], 1, 32, "ui renderer")
    if ui["fallback_reason"] is not None:
        string(ui["fallback_reason"], 1, 512, "ui fallback reason")
    if (ui["mode"] == "headless-fallback") != (
            ui["fallback_reason"] is not None):
        reject("ui mode and fallback reason disagree")

error = document["error"]
if document["outcome"] == "success":
    if error is not None:
        reject("success result contains an error")
else:
    exact_object(error, ("class", "message"), "error")
    if (not isinstance(error["class"], str) or
            not re.fullmatch(r"^[A-Za-z][A-Za-z0-9_]{0,127}$",
                             error["class"])):
        reject("invalid error class")
    string(error["message"], 1, 512, "error message")

print(json.dumps(document, ensure_ascii=True, sort_keys=True,
                 separators=(",", ":")))
PY
}

nxbootstrap_phase_event preflight START bootstrap 6190 || {
  nxbootstrap_finish
  exit 1
}

# The executable is itself required and is touched before the owner-data phase.
NXBOOTSTRAP_EXECUTABLE=$(readlink -f "$GAMEDIR/riptidegp1-nextos" 2>/dev/null) || NXBOOTSTRAP_EXECUTABLE=""
case "$NXBOOTSTRAP_EXECUTABLE" in
  "$GAMEDIR"/*) ;;
  *) NXBOOTSTRAP_EXECUTABLE="" ;;
esac
if [ -z "$NXBOOTSTRAP_EXECUTABLE" ] || [ ! -f "$NXBOOTSTRAP_EXECUTABLE" ] || \
   [ ! -s "$NXBOOTSTRAP_EXECUTABLE" ] || [ -L "$GAMEDIR/riptidegp1-nextos" ]; then
  echo "ERROR: executable is missing or unsafe: riptidegp1-nextos"
  nxbootstrap_finish
  exit 1
fi

# Dynamic-loader (PT_INTERP) preflight: an ELF whose interpreter is absent
# exec()s with ENOENT, which the shell reports as "No such file or directory"
# for the binary and a bare status 127 -- a black screen that looks like a
# broken port but is a missing device runtime. Textbook case: a 32-bit ARMHF
# port on a 64-bit-only CFW with no 32-bit ARM runtime (spruce/Miyoo Flip:
# /lib/ld-linux-armhf.so.3 absent). `grep -a` reads the early .interp; a static
# or unreadable ELF yields nothing and skips the check (never a false block).
# Prefix that runs the game THROUGH an explicit loader (empty for every normal
# port -- the run line then executes "$BIN" byte-identically). Only set below,
# for the spruce/Miyoo-Flip case where the 32-bit loader lives off the default
# path.
NXBOOTSTRAP_INTERP_PREFIX=""
NXBOOTSTRAP_INTERP=$(LC_ALL=C grep -a -o -m1 -E '/lib(32|64)?/ld-[A-Za-z0-9._-]*\.so[A-Za-z0-9._-]*' "$NXBOOTSTRAP_EXECUTABLE" 2>/dev/null | head -n1)
if [ -n "$NXBOOTSTRAP_INTERP" ] && [ ! -e "$NXBOOTSTRAP_INTERP" ]; then
  # The interpreter is absent at the exact path baked into the ELF. Before
  # giving up, look for the SAME loader elsewhere: some CFWs mount their 32-bit
  # runtime off the default path -- spruceOS/Miyoo Flip assembles a 32-bit chroot
  # at boot and copies ld-linux-armhf.so.3 under /usr/lib and /usr/lib32. If we
  # find it, run the game THROUGH that loader with an explicit --library-path
  # (additive: this branch is only reached when the game would otherwise abort).
  NXBOOTSTRAP_INTERP_BASE=$(basename "$NXBOOTSTRAP_INTERP")
  NXBOOTSTRAP_INTERP_ALT=""
  for cand in \
    "/usr/lib/$NXBOOTSTRAP_INTERP_BASE" \
    "/usr/lib32/$NXBOOTSTRAP_INTERP_BASE" \
    "/lib32/$NXBOOTSTRAP_INTERP_BASE" \
    "/mnt/SDCARD/spruce/flip/$NXBOOTSTRAP_INTERP_BASE" \
    "/mnt/SDCARD/spruce/flip/muOS/usr/lib/$NXBOOTSTRAP_INTERP_BASE" \
    "/mnt/SDCARD/Persistent/.32bit_chroot/usr/lib/$NXBOOTSTRAP_INTERP_BASE" \
    "/mnt/SDCARD/Persistent/.32bit_chroot/lib/$NXBOOTSTRAP_INTERP_BASE"; do
    [ -e "$cand" ] && { NXBOOTSTRAP_INTERP_ALT="$cand"; break; }
  done
  if [ -n "$NXBOOTSTRAP_INTERP_ALT" ]; then
    # Diretorios confirmados nas IMAGENS oficiais (spruce v4.3.4): o muOS
    # reduzido tem SDL2/EGL/GLES ARMHF em usr/lib (nao so lib32) e o chroot
    # 32-bit monta em /mnt/SDCARD/Persistent/.32bit_chroot.
    NXBOOTSTRAP_INTERP_LIBS="$GAMEDIR:$GAMEDIR/lib:/usr/lib32:/lib32:/mnt/SDCARD/spruce/flip/muOS/usr/lib:/mnt/SDCARD/spruce/flip/muOS/lib:/mnt/SDCARD/spruce/flip/muOS/lib32:/mnt/SDCARD/spruce/flip/muOS/usr/lib32:/mnt/SDCARD/Persistent/.32bit_chroot/usr/lib:/mnt/SDCARD/Persistent/.32bit_chroot/lib${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
    NXBOOTSTRAP_INTERP_PREFIX="$NXBOOTSTRAP_INTERP_ALT --library-path $NXBOOTSTRAP_INTERP_LIBS"
    echo "NOTE: interpreter $NXBOOTSTRAP_INTERP is absent at its default path, but $NXBOOTSTRAP_INTERP_ALT exists; launching riptidegp1-nextos through it."
  else
    echo "ERROR: riptidegp1-nextos cannot run here: dynamic loader $NXBOOTSTRAP_INTERP is missing."
    case "$NXBOOTSTRAP_INTERP" in
      *armhf*|*ld-linux.so.3) echo "  32-bit ARM (ARMHF) port, but this CFW has no 32-bit ARM runtime on any known path; use a CFW with 32-bit multiarch (Knulli/ROCKNIX), fix the 32-bit mount (spruce/Miyoo Flip), or use an AArch64 build." ;;
      *aarch64*|*ld-linux-aarch64*) echo "  64-bit ARM (AArch64) port, but this device has no 64-bit ARM runtime." ;;
      *) echo "  this CFW does not provide the runtime this port was built for." ;;
    esac
    nxbootstrap_phase_event preflight ERROR bootstrap 6198 || true
    nxbootstrap_finish
    exit 1
  fi
fi

# Exec bits do not survive zip/FAT/Windows extraction.
$ESUDO chmod +x "$NXBOOTSTRAP_EXECUTABLE" "$GAMEDIR/nxextract-ui" \
  "$GAMEDIR/nxsplash-nextos" 2>/dev/null || true
if [ -z "$NXBOOTSTRAP_SELECTED_GENERATION" ] || \
   ! nxbootstrap_generation_is_v2 \
       "$NXRUNTIME_DIR/generations/$NXBOOTSTRAP_SELECTED_GENERATION"; then
  # Legacy ZIPs did not authenticate per-file modes. Generation-v2 already
  # healed every declared hook to its exact 0644/0755 mode; do not widen a
  # sourced 0644 hook after that closed validation.
  $ESUDO chmod +x "$GAMEDIR"/*.sh 2>/dev/null || true
fi
$ESUDO chmod 666 "$CUR_TTY" /dev/uinput 2>/dev/null || true

# Keep the text console dark across the KMSDRM transition: a slow-loading
# engine (Unity/IL2CPP) would otherwise leave the tty visible -- PortMaster
# get_controls output and boot text -- until its GL window covers the screen,
# and the frontend hand-off already resets it (\033c) on exit. Hide the cursor
# and clear the screen; harmless on fbdev where nothing overlaps.
[ -n "$CUR_TTY" ] && [ -c "$CUR_TTY" ] && \
  printf '\033[?25l\033[2J\033[H' > "$CUR_TTY" 2>/dev/null || true

# One stable lock per port ID, outside the ROM. Replacing the ELF cannot create
# a new lock inode and allow a second game to fight for fb0/audio/input.
# V3-RUNTIME-01: enumerate stale processes whose executable lives under this
# port, including a replaced binary shown as "... (deleted)". A live process
# of the SAME generation means the game is already open: refuse a second
# instance with a readable message. An old/stale one is terminated in a
# controlled way and must be gone before we continue; two instances fighting
# for GPU/framebuffer/audio can freeze the device.
nxbootstrap_stale_sweep() {
  local proc_entry proc_pid proc_exe proc_generation waited
  for proc_entry in /proc/[0-9]*; do
    proc_pid=${proc_entry#/proc/}
    [ "$proc_pid" != "$$" ] || continue
    proc_exe=$(readlink "$proc_entry/exe" 2>/dev/null) || continue
    case "$proc_exe" in
      "$GAMEDIR"/*|"$GAMEDIR"/*" (deleted)") ;;
      *) continue ;;
    esac
    # The stable lock is acquired BEFORE this sweep. A conforming live child
    # therefore prevents us from reaching here at all. This environment check
    # protects an orphan whose runtime closed the inherited lock descriptor:
    # the same generation is a live instance, never "stale" and never killed.
    proc_generation=$(tr '\000' '\n' < "$proc_entry/environ" 2>/dev/null |
      sed -n 's/^NXBOOTSTRAP_HEALTH_GENERATION=//p' | head -n 1)
    if [ -n "$proc_generation" ] && \
       [ "$proc_generation" = "${NXBOOTSTRAP_SELECTED_GENERATION:-none}" ]; then
      nxbootstrap_runtime_event NXR0003 "same generation is already alive pid=$proc_pid; not terminating it and not starting a second instance"
      echo "ERROR NXR0003: the same generation is already running (pid $proc_pid); not starting a second instance"
      nxbootstrap_finish
      exit 1
    fi
    nxbootstrap_runtime_event NXR0001 "stale process pid=$proc_pid exe=${proc_exe##*/}"
    builtin kill -TERM "$proc_pid" 2>/dev/null || true
    waited=0
    while [ -d "$proc_entry" ] && [ "$waited" -lt 5 ]; do
      sleep 1
      waited=$((waited + 1))
    done
    if [ -d "$proc_entry" ]; then
      builtin kill -KILL "$proc_pid" 2>/dev/null || true
      sleep 1
    fi
    if [ -d "$proc_entry" ]; then
      nxbootstrap_runtime_event NXR0002 "a previous instance (pid $proc_pid) is still alive and could not be terminated; not starting a second instance"
      echo "ERROR NXR0002: a previous instance (pid $proc_pid) is still alive and could not be terminated; not starting a second instance"
      nxbootstrap_finish
      exit 1
    fi
  done
}

NXBOOTSTRAP_LOCK_ROOT=${XDG_RUNTIME_DIR:-}
if [ "${NXBOOTSTRAP_LOCK_ROOT#/}" = "$NXBOOTSTRAP_LOCK_ROOT" ] || \
   [ ! -d "$NXBOOTSTRAP_LOCK_ROOT" ] || [ -L "$NXBOOTSTRAP_LOCK_ROOT" ] || \
   [ ! -O "$NXBOOTSTRAP_LOCK_ROOT" ] || [ ! -w "$NXBOOTSTRAP_LOCK_ROOT" ] || \
   [ ! -x "$NXBOOTSTRAP_LOCK_ROOT" ]; then
  NXBOOTSTRAP_LOCK_ROOT=/tmp
fi
if [ ! -d "$NXBOOTSTRAP_LOCK_ROOT" ] || [ -L "$NXBOOTSTRAP_LOCK_ROOT" ] || \
   [ ! -w "$NXBOOTSTRAP_LOCK_ROOT" ] || [ ! -x "$NXBOOTSTRAP_LOCK_ROOT" ]; then
  echo "ERROR: no safe runtime directory for the instance lock"
  nxbootstrap_finish
  exit 1
fi
NXBOOTSTRAP_LOCK_ROOT=$(cd "$NXBOOTSTRAP_LOCK_ROOT" 2>/dev/null && pwd -P) || {
  echo "ERROR: no safe runtime directory for the instance lock"
  nxbootstrap_finish
  exit 1
}
case "$NXBOOTSTRAP_LOCK_ROOT" in
  "$GAMEDIR"|"$GAMEDIR"/*)
    echo "ERROR: instance lock directory must be outside the game"
    nxbootstrap_finish
    exit 1
    ;;
esac
NXBOOTSTRAP_LOCK_DIR="$NXBOOTSTRAP_LOCK_ROOT/.nxbootstrap-${UID:-$(id -u)}"
if [ ! -e "$NXBOOTSTRAP_LOCK_DIR" ] && [ ! -L "$NXBOOTSTRAP_LOCK_DIR" ]; then
  (umask 077; mkdir "$NXBOOTSTRAP_LOCK_DIR") 2>/dev/null || true
fi
if [ ! -d "$NXBOOTSTRAP_LOCK_DIR" ] || [ -L "$NXBOOTSTRAP_LOCK_DIR" ] || \
   [ ! -O "$NXBOOTSTRAP_LOCK_DIR" ] || [ ! -w "$NXBOOTSTRAP_LOCK_DIR" ] || \
   [ ! -x "$NXBOOTSTRAP_LOCK_DIR" ] || \
   ! chmod 0700 "$NXBOOTSTRAP_LOCK_DIR" 2>/dev/null; then
  echo "ERROR: unsafe runtime directory for the instance lock"
  nxbootstrap_finish
  exit 1
fi
NXBOOTSTRAP_LOCK_FILE="$NXBOOTSTRAP_LOCK_DIR/nxport-riptidegp1.flock"
if [ -e "$NXBOOTSTRAP_LOCK_FILE" ] || [ -L "$NXBOOTSTRAP_LOCK_FILE" ]; then
  if [ ! -f "$NXBOOTSTRAP_LOCK_FILE" ] || [ -L "$NXBOOTSTRAP_LOCK_FILE" ] || \
     [ ! -O "$NXBOOTSTRAP_LOCK_FILE" ]; then
    echo "ERROR: unsafe instance lock file"
    nxbootstrap_finish
    exit 1
  fi
fi
NXBOOTSTRAP_OLD_UMASK=$(umask)
umask 077
{ exec 9>&-; } 2>/dev/null || true
if ! { exec 9>>"$NXBOOTSTRAP_LOCK_FILE"; } 2>/dev/null; then
  umask "$NXBOOTSTRAP_OLD_UMASK"
  echo "ERROR: cannot open the instance lock"
  nxbootstrap_finish
  exit 1
fi
umask "$NXBOOTSTRAP_OLD_UMASK"
# POSIX/BusyBox/Toybox ls supplies nlink; Bash -ef proves the opened inode.
# Never depend on external stat: some supported muOS images omit it.
NXBOOTSTRAP_LOCK_META=()
IFS=' ' read -r -a NXBOOTSTRAP_LOCK_META \
  <<< "$(LC_ALL=C command ls -Lldn /proc/self/fd/9 2>/dev/null)"
NXBOOTSTRAP_LOCK_LINKS=${NXBOOTSTRAP_LOCK_META[1]:-}
if [ ! -f "$NXBOOTSTRAP_LOCK_FILE" ] || [ -L "$NXBOOTSTRAP_LOCK_FILE" ] || \
   [ ! -O "$NXBOOTSTRAP_LOCK_FILE" ] || [ "$NXBOOTSTRAP_LOCK_LINKS" != 1 ] || \
   ! [ "$NXBOOTSTRAP_LOCK_FILE" -ef /proc/self/fd/9 ]; then
  { exec 9>&-; } 2>/dev/null || true
  echo "ERROR: instance lock identity is unsafe"
  nxbootstrap_finish
  exit 1
fi
unset NXBOOTSTRAP_LOCK_META NXBOOTSTRAP_LOCK_LINKS
# Some BusyBox firmwares ship no flock applet. Without it, fail closed through
# an owner-stamped mkdir lock. An existing directory is never reclaimed here:
# shell has no atomic compare-and-delete primitive that can distinguish a dead
# owner from a live creator still between mkdir and its owner write. Explicit
# maintenance may remove a proved-dead lock; a launcher never guesses.
if command -v flock >/dev/null 2>&1; then
  if ! flock -n 9; then
    echo "another instance holds the lock; not double-launching"
    nxbootstrap_finish
    exit 1
  fi
else
  NXBOOTSTRAP_FALLBACK_LOCK_DIR="$NXBOOTSTRAP_LOCK_FILE.d"
  NXBOOTSTRAP_FALLBACK_LOCK_TOKEN=$NXOBS_RUN_ID
  case "$NXBOOTSTRAP_FALLBACK_LOCK_TOKEN" in
    ''|*[!A-Za-z0-9._-]*)
      echo "ERROR: invalid fallback instance lock token"
      nxbootstrap_finish
      exit 1
      ;;
  esac
  if ! (umask 077; mkdir "$NXBOOTSTRAP_FALLBACK_LOCK_DIR") 2>/dev/null; then
    echo "another instance holds the lock; not double-launching (no flock on this firmware)"
    nxbootstrap_finish
    exit 1
  fi
  NXBOOTSTRAP_FALLBACK_OWNER_FILE="$NXBOOTSTRAP_FALLBACK_LOCK_DIR/owner"
  if ! (umask 077; set -C; printf 'pid=%s token=%s\n' \
       "$$" "$NXBOOTSTRAP_FALLBACK_LOCK_TOKEN" > \
       "$NXBOOTSTRAP_FALLBACK_OWNER_FILE") 2>/dev/null || \
     [ ! -d "$NXBOOTSTRAP_FALLBACK_LOCK_DIR" ] || \
     [ -L "$NXBOOTSTRAP_FALLBACK_LOCK_DIR" ] || \
     [ ! -O "$NXBOOTSTRAP_FALLBACK_LOCK_DIR" ] || \
     [ ! -f "$NXBOOTSTRAP_FALLBACK_OWNER_FILE" ] || \
     [ -L "$NXBOOTSTRAP_FALLBACK_OWNER_FILE" ] || \
     [ ! -O "$NXBOOTSTRAP_FALLBACK_OWNER_FILE" ]; then
    echo "ERROR: cannot stamp the fallback instance lock; explicit cleanup is required"
    nxbootstrap_finish
    exit 1
  fi
  NXBOOTSTRAP_FALLBACK_LOCK_ACQUIRED=1
  unset NXBOOTSTRAP_FALLBACK_OWNER_FILE
  # Released only by nxbootstrap_on_exit after exact PID/token revalidation;
  # never install another EXIT trap here because it would replace that funnel.
fi
# Only after the stable per-port lock is ours may an unprotected process be
# classified as an old/stale generation. Previously the sweep ran first and
# killed a healthy current game before `flock -n` could refuse the duplicate.
nxbootstrap_stale_sweep
# Health proof lives beside the validated process lock, never on FAT/exFAT or
# inside the game tree. The child must publish the exact versioned JSON with an
# exclusive temp + rename; a log line, PID lifetime or exit status is not
# authority. The unique run_id makes a receipt non-reusable across launches.
NXBOOTSTRAP_HEALTH_FILE="$NXBOOTSTRAP_LOCK_DIR/health-riptidegp1-$NXOBS_RUN_ID.json"
if [ -e "$NXBOOTSTRAP_HEALTH_FILE" ] || [ -L "$NXBOOTSTRAP_HEALTH_FILE" ]; then
  echo "ERROR: health receipt path unexpectedly exists"
  nxbootstrap_finish
  exit 1
fi
NXBOOTSTRAP_HEALTH_SCHEMA=org.nextos.nxruntime.health
NXBOOTSTRAP_HEALTH_SCHEMA_VERSION=1
NXBOOTSTRAP_HEALTH_RUN_ID=$NXOBS_RUN_ID
NXBOOTSTRAP_HEALTH_GENERATION=${NXBOOTSTRAP_SELECTED_GENERATION:-none}
NXBOOTSTRAP_HEALTH_PORT_ID=riptidegp1
export NXBOOTSTRAP_HEALTH_FILE NXBOOTSTRAP_HEALTH_SCHEMA \
  NXBOOTSTRAP_HEALTH_SCHEMA_VERSION NXBOOTSTRAP_HEALTH_RUN_ID \
  NXBOOTSTRAP_HEALTH_GENERATION NXBOOTSTRAP_HEALTH_PORT_ID
readonly NXBOOTSTRAP_HEALTH_FILE NXBOOTSTRAP_HEALTH_SCHEMA \
  NXBOOTSTRAP_HEALTH_SCHEMA_VERSION NXBOOTSTRAP_HEALTH_RUN_ID \
  NXBOOTSTRAP_HEALTH_GENERATION NXBOOTSTRAP_HEALTH_PORT_ID
# A conclusive frame-proof failure is a separate, run-bound authority. It can
# veto health, but an absent/malformed/inconclusive receipt never fabricates a
# verdict. The producer publishes one canonical 0600 line by atomic rename.
NXBOOTSTRAP_VIDEO_FILE="$NXBOOTSTRAP_LOCK_DIR/video-riptidegp1-$NXOBS_RUN_ID.json"
if [ -e "$NXBOOTSTRAP_VIDEO_FILE" ] || [ -L "$NXBOOTSTRAP_VIDEO_FILE" ]; then
  echo "ERROR: video receipt path unexpectedly exists"
  nxbootstrap_finish
  exit 1
fi
NXBOOTSTRAP_VIDEO_SCHEMA=org.nextos.nxruntime.video-proof
NXBOOTSTRAP_VIDEO_SCHEMA_VERSION=1
export NXBOOTSTRAP_VIDEO_FILE NXBOOTSTRAP_VIDEO_SCHEMA \
  NXBOOTSTRAP_VIDEO_SCHEMA_VERSION

readonly NXBOOTSTRAP_VIDEO_FILE NXBOOTSTRAP_VIDEO_SCHEMA \
  NXBOOTSTRAP_VIDEO_SCHEMA_VERSION NXBOOTSTRAP_VIDEO_REQUIRED
BIN="$GAMEDIR/riptidegp1-nextos"
# 0.6.24: fonte CANONICA de auto-localizacao do guest. Rodando atraves do
# ld-linux explicito (CFW 64-bit-only com runtime ARMHF fora do caminho), o
# /proc/self/exe do jogo aponta pro LD.SO — loaders que se localizavam por ele
# perdiam a propria pasta (caso de campo: gamedir virou a pasta do loader e o
# preflight recusou). NXBOOTSTRAP_EXE e sempre o caminho REAL do executavel.
export NXBOOTSTRAP_EXE="$BIN"

if command -v pm_platform_helper >/dev/null 2>&1; then
  if pm_platform_helper "$BIN"; then
    echo "pm_platform_helper completed before game launch"
  else
    NXBOOTSTRAP_PLATFORM_STATUS=$?
    echo "WARNING: pm_platform_helper returned status $NXBOOTSTRAP_PLATFORM_STATUS; continuing"
  fi
fi

# A CFW platform module may replace PortMaster's default helper without closing
# the live pugwash dialog. The game then runs (including audio/input) behind the
# dialog's black surface. Act only on PortMaster's exact live FIFO and through
# its own close API; unsafe or unprovable ownership fails before game launch.
NXBOOTSTRAP_DIALOG_PIPE=${PM_PIPE:-}
if [ -n "$NXBOOTSTRAP_DIALOG_PIPE" ] && \
   { [ -e "$NXBOOTSTRAP_DIALOG_PIPE" ] || [ -L "$NXBOOTSTRAP_DIALOG_PIPE" ]; }; then
  if [ ! -p "$NXBOOTSTRAP_DIALOG_PIPE" ] || [ -L "$NXBOOTSTRAP_DIALOG_PIPE" ]; then
    echo "ERROR: PortMaster dialog handoff failed: PM_PIPE is not a live non-symlink FIFO"
    nxbootstrap_finish
    exit 1
  fi
  if ! declare -F PortMasterDialogExit >/dev/null 2>&1; then
    echo "ERROR: PortMaster dialog handoff failed: close API unavailable while PM_PIPE is active"
    nxbootstrap_finish
    exit 1
  fi
  if PortMasterDialogExit; then
    :
  else
    NXBOOTSTRAP_PLATFORM_STATUS=$?
    echo "ERROR: PortMaster dialog handoff failed: close API returned status $NXBOOTSTRAP_PLATFORM_STATUS"
    nxbootstrap_finish
    exit 1
  fi
  if [ -e "$NXBOOTSTRAP_DIALOG_PIPE" ] || [ -L "$NXBOOTSTRAP_DIALOG_PIPE" ]; then
    echo "ERROR: PortMaster dialog handoff failed: PM_PIPE remained after close request"
    nxbootstrap_finish
    exit 1
  fi
  echo "PortMaster dialog closed after platform helper"
fi
unset NXBOOTSTRAP_DIALOG_PIPE NXBOOTSTRAP_PLATFORM_STATUS

nxbootstrap_phase_event preflight OK bootstrap 6191 || {
  nxbootstrap_finish
  exit 1
}


# NXExtract owner-data phase (BYO data): runs before the game, other process.
NXDIR=""
[ -f "$GAMEDIR/nxextract/run-extractor.sh" ] && NXDIR="$GAMEDIR/nxextract"
[ -z "$NXDIR" ] && [ -f "$GAMEDIR/run-extractor.sh" ] && NXDIR="$GAMEDIR"
NXEXTRACT_REQUESTED=1
if [ "$NXEXTRACT_REQUESTED" = 1 ]; then
  nxbootstrap_phase_event nxextract START bootstrap 6200 || {
    nxbootstrap_finish
    exit 1
  }
  NXEXTRACT_INCOMPLETE=0
  [ -n "$NXDIR" ] && [ ! -L "$NXDIR" ] || NXEXTRACT_INCOMPLETE=1
  for nxfile in "$GAMEDIR/extractor.json" "$NXDIR/run-extractor.sh" \
    "$NXDIR/nxextract.py" "$NXDIR/nxextract-runtime-env.sh" \
    "$NXDIR/nxextract-ui"; do
    [ -f "$nxfile" ] && [ -s "$nxfile" ] && [ ! -L "$nxfile" ] || NXEXTRACT_INCOMPLETE=1
  done
  if [ "$NXEXTRACT_INCOMPLETE" = 1 ]; then
    echo "ERROR: incomplete NXExtract integration"
    nxbootstrap_phase_event nxextract ERROR bootstrap 6202 || true
    nxbootstrap_finish
    exit 1
  fi
  $ESUDO chmod +x "$NXDIR/nxextract-ui" 2>/dev/null || true
  if [ ! -x "$NXDIR/nxextract-ui" ]; then
    echo "ERROR: mandatory NXExtract UI is not executable"
    nxbootstrap_phase_event nxextract ERROR bootstrap 6202 || true
    nxbootstrap_finish
    exit 1
  fi
  NXEXTRACT_RESULT_FILE="$GAMEDIR/nxextract-result.json"
  if [ -e "$NXEXTRACT_RESULT_FILE" ] || [ -L "$NXEXTRACT_RESULT_FILE" ]; then
    if [ ! -f "$NXEXTRACT_RESULT_FILE" ] || [ -L "$NXEXTRACT_RESULT_FILE" ]; then
      echo "ERROR: stale NXExtract result path is unsafe"
      nxbootstrap_phase_event nxextract ERROR bootstrap 6202 || true
      nxbootstrap_finish
      exit 1
    fi
    mv -f "$NXEXTRACT_RESULT_FILE" \
      "$GAMEDIR/nxextract-result.prev.json" || {
        echo "ERROR: could not rotate the previous NXExtract result"
        nxbootstrap_phase_event nxextract ERROR bootstrap 6202 || true
        nxbootstrap_finish
        exit 1
      }
  fi
  # The firmware python3 must start: a corrupted stdlib bytecode cache (muOS,
  # "bad marshal data" in encodings) kills it before NXExtract sees the APK.
  # Retry with a private cache, then fail loudly instead of "result malformed".
  NXEXTRACT_PY_PROBE='import encodings, json, zipfile, hashlib'
  if ! python3 -B -c "$NXEXTRACT_PY_PROBE" >/dev/null 2>&1; then
    if PYTHONPYCACHEPREFIX="$GAMEDIR/.nxpycache" python3 -B -c "$NXEXTRACT_PY_PROBE" >/dev/null 2>&1; then
      export PYTHONPYCACHEPREFIX="$GAMEDIR/.nxpycache"
      echo "WARN: system python bytecode cache is broken; using $GAMEDIR/.nxpycache"
    else
      echo "ERROR: the firmware's python3 cannot start (corrupted stdlib/bytecode);"
      echo "ERROR: NXExtract needs a working python3 -- reinstall/update the CFW."
      nxbootstrap_phase_event nxextract ERROR bootstrap 6209 || true
      nxbootstrap_finish
      exit 1
    fi
  fi
  NXEXTRACT_STATUS=0
  NXEXTRACT_GAME_DIR="$GAMEDIR" \
    bash "$NXDIR/nxextract-runtime-env.sh" \
    bash "$NXDIR/run-extractor.sh" || NXEXTRACT_STATUS=$?
  NXEXTRACT_RESULT_STATUS=0
  NXEXTRACT_SUMMARY=""
  if [ -f "$NXEXTRACT_RESULT_FILE" ] && [ ! -L "$NXEXTRACT_RESULT_FILE" ]; then
    if NXEXTRACT_SUMMARY=$(nxbootstrap_validate_nxextract_result \
      "$NXEXTRACT_RESULT_FILE" "$NXEXTRACT_STATUS"); then
      :
    else
      NXEXTRACT_RESULT_STATUS=$?
    fi
  else
    NXEXTRACT_RESULT_STATUS=1
  fi
  if [ "$NXEXTRACT_RESULT_STATUS" -ne 0 ]; then
    echo "ERROR: NXExtract terminal result is missing, unsafe or malformed"
    nxbootstrap_phase_event nxextract ERROR bootstrap 6202 \
      "$NXEXTRACT_STATUS" || true
    nxbootstrap_finish
    if [ "$NXEXTRACT_STATUS" -ne 0 ]; then exit "$NXEXTRACT_STATUS"; fi
    exit 1
  fi
  printf 'NXEXTRACT_RESULT %s\n' "$NXEXTRACT_SUMMARY"
  if [ "$NXEXTRACT_STATUS" -ne 0 ]; then
    echo "ERROR: game data installation did not complete"
    nxbootstrap_phase_event nxextract ERROR extractor 6203 \
      "$NXEXTRACT_STATUS" || true
    nxbootstrap_finish
    exit "$NXEXTRACT_STATUS"
  fi
  nxbootstrap_phase_event nxextract OK extractor 6201 || {
    nxbootstrap_finish
    exit 1
  }
fi
unset NXDIR NXEXTRACT_REQUESTED NXEXTRACT_INCOMPLETE nxfile \
  NXEXTRACT_RESULT_FILE NXEXTRACT_STATUS NXEXTRACT_RESULT_STATUS \
  NXEXTRACT_SUMMARY

# Manifest-owned payload gate: extraction/prepare must finish before launch.
NXBOOTSTRAP_REQUIRED_FILES='riptidegp1-nextos
nxsplash-nextos
lib/libSDL3.so.0
port-env.sh
gamedata/lib/arm64-v8a/libmain.so
gamedata/assets/Base.apf'
while IFS= read -r required_file; do
  [ -n "$required_file" ] || continue
