RGP_SKIP_SPLASH=0
if [ "${nxbootstrap_state_active:-}" = "$NXBOOTSTRAP_GENERATION_ID" ] && \
   [ "${nxbootstrap_state_failures:-0}" = 0 ] && \
   [ ! -e "$NXRUNTIME_DIR/deep-verify-next" ] && \
   [ ! -L "$NXRUNTIME_DIR/deep-verify-next" ] && \
   [ -f "$GAMEDIR/.nxextract-riptidegp1.json" ] && \
   [ ! -L "$GAMEDIR/.nxextract-riptidegp1.json" ]; then
