readonly NXBOOTSTRAP_ANALOG_STICKS_HINT
[ -f "$GAMEDIR/port-env.sh" ] && [ ! -L "$GAMEDIR/port-env.sh" ] && . "$GAMEDIR/port-env.sh"

# Host phase ends here: game/private library paths must never contaminate
# pm_platform_helper or the setup tools above, so they enter only now.
# SDL1/SDL2 belong to the CFW/PortMaster integration. A local provider in
# any game-visible library root would shadow it before the runtime can repair
# input or video. SDL3 stays eligible only for the separately declared
# Godot/native-SDL3 exception and is deliberately not matched here.
nxbootstrap_sdl_name_is_sdl12() {
  local base=${1##*/}
  base=${base,,}
  case "$base" in
    libsdl3|libsdl3.*|libsdl3_*|libsdl3+*|libsdl3-*) return 1 ;;
    libsdl2|libsdl2.*|libsdl2_*|libsdl2+*|libsdl2-*|\
    libsdl|libsdl.*|libsdl_*|libsdl+*|libsdl-*) return 0 ;;
  esac
  return 1
}
nxbootstrap_sdl_file_has_pair() {
  local candidate=$1 first=$2 second=$3
  LD_PRELOAD= SDL_DYNAMIC_API= LC_ALL=C command grep -a -F -q "$first" \
    "$candidate" 2>/dev/null && \
  LD_PRELOAD= SDL_DYNAMIC_API= LC_ALL=C command grep -a -F -q "$second" \
    "$candidate" 2>/dev/null
}
nxbootstrap_file_looks_sdl12() {
  local candidate=$1 base=${1##*/} lowered
  lowered=${base,,}
  case "$lowered" in
    libsdl3|libsdl3.*|libsdl3_*|libsdl3+*|libsdl3-*) return 1 ;;
  esac
  nxbootstrap_sdl_name_is_sdl12 "$base" && return 0
  nxbootstrap_sdl_file_has_pair "$candidate" Mix_OpenAudio Mix_Quit ||
    nxbootstrap_sdl_file_has_pair "$candidate" IMG_Init IMG_Quit ||
    nxbootstrap_sdl_file_has_pair "$candidate" TTF_Init TTF_Quit ||
    nxbootstrap_sdl_file_has_pair "$candidate" SDLNet_Init SDLNet_Quit ||
    nxbootstrap_sdl_file_has_pair "$candidate" rotozoomSurface pixelColor ||
    nxbootstrap_sdl_file_has_pair "$candidate" GPU_Init GPU_Quit ||
    nxbootstrap_sdl_file_has_pair "$candidate" Sound_Init Sound_Quit ||
    nxbootstrap_sdl_file_has_pair "$candidate" RTF_Init RTF_Quit ||
    nxbootstrap_sdl_file_has_pair "$candidate" FC_CreateFont FC_FreeFont ||
    {
      LD_PRELOAD= SDL_DYNAMIC_API= LC_ALL=C command grep -a -F -q \
        SDL_Init "$candidate" 2>/dev/null &&
      LD_PRELOAD= SDL_DYNAMIC_API= LC_ALL=C command grep -a -F -q \
        SDL_PollEvent "$candidate" 2>/dev/null &&
      { nxbootstrap_sdl_file_has_pair "$candidate" \
          SDL_CreateWindow SDL_GetVersion ||
        nxbootstrap_sdl_file_has_pair "$candidate" \
          SDL_SetVideoMode SDL_Linked_Version; }
    }
}
nxbootstrap_reject_private_sdl12() {
  local root=$1 candidate
  [ -d "$root" ] || return 0
  for candidate in "$root"/[lL][iI][bB][sS][dD][lL]*; do
    [ -e "$candidate" ] || [ -L "$candidate" ] || continue
    nxbootstrap_sdl_name_is_sdl12 "$candidate" || continue
    echo "ERROR: private SDL1/SDL2 provider is forbidden: $candidate"
    return 1
  done
}
for nxbootstrap_sdl_root in "$GAMEDIR" "$GAMEDIR"/lib; do
  nxbootstrap_reject_private_sdl12 "$nxbootstrap_sdl_root" || {
    nxbootstrap_finish
    exit 1
  }
done
unset nxbootstrap_sdl_root

nxbootstrap_append_inherited_library_paths() {
  local inherited=$1 directory canonical
  NXBOOTSTRAP_FILTERED_INHERITED=""
  while IFS= read -r directory; do
    [ -n "$directory" ] && [ "${directory#/}" != "$directory" ] || continue
    canonical=$(readlink -f -- "$directory" 2>/dev/null) || continue
    [ -d "$canonical" ] || continue
    case "$canonical" in
      "$NXBOOTSTRAP_PHYSICAL_GAMEDIR"|"$NXBOOTSTRAP_PHYSICAL_GAMEDIR"/*)
        echo "LIBRARY PATH: removed inherited port-local root"
        continue
        ;;
    esac
    case ":$NXBOOTSTRAP_FILTERED_INHERITED:" in
      *:"$canonical":*) ;;
      *) NXBOOTSTRAP_FILTERED_INHERITED="${NXBOOTSTRAP_FILTERED_INHERITED:+$NXBOOTSTRAP_FILTERED_INHERITED:}$canonical" ;;
    esac
  done < <(printf '%s\n' "${inherited//:/$'\n'}")
}
# Firmware/PortMaster overlays first; preserve distro-local providers before
# the system defaults, then append the game's own directory.
LIBS=""
for d in "$controlfolder/libs" "$controlfolder/libs.aarch64" \
         /usr/local/lib/aarch64-linux-gnu /usr/local/lib64 /usr/local/lib \
         /usr/lib/aarch64-linux-gnu /lib/aarch64-linux-gnu \
         /usr/lib64 /lib64 /usr/lib /lib; do
  [ -n "$d" ] && [ -d "$d" ] && LIBS="${LIBS:+$LIBS:}$d"
done
:
export LD_LIBRARY_PATH="${LIBS}:$GAMEDIR:$GAMEDIR/lib${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"

NXBOOTSTRAP_SDL_PROVIDER=legacy
NXBOOTSTRAP_SDL_RESOLUTION_PATH=$LD_LIBRARY_PATH
export NXBOOTSTRAP_SDL_PROVIDER NXBOOTSTRAP_SDL_RESOLUTION_PATH
echo "SDL PROVIDER: declared=$NXBOOTSTRAP_SDL_PROVIDER order=portmaster-before-firmware backend=unforced search=$NXBOOTSTRAP_SDL_RESOLUTION_PATH"
:

nxbootstrap_install_exit_trap
nxbootstrap_install_early_traps

# Manifest-owned runtime contract: reassert after every mutable shell hook.
case "$NXBOOTSTRAP_ANALOG_STICKS_HINT" in
  0|1|2) export NXINPUT_ANALOG_STICKS_HINT="$NXBOOTSTRAP_ANALOG_STICKS_HINT" ;;
  *) unset NXINPUT_ANALOG_STICKS_HINT ;;
esac
export NXCOMPAT_PORT_ID=riptidegp1
# The guest's lexical identity is the LOGICAL root it was invoked under
# (V3-UPDATE-01); the physical root stays available for framework-side I/O.
# Both resolve to the same inode (proven by the two-tree -ef guard above).
export NXCOMPAT_GAME_DIR="$NXBOOTSTRAP_LOGICAL_GAMEDIR"
export NXCOMPAT_GAME_DIR_PHYSICAL="$NXBOOTSTRAP_PHYSICAL_GAMEDIR"
export NXCOMPAT_REQUIRED_CAPABILITIES='host.portmaster
graphics.window
graphics.gles2
graphics.egl
graphics.egl-config
graphics.drawable
audio.output-open
input.controller-mapping
input.controller-api'
export NXCOMPAT_ENABLED_QUIRKS=''
export NXCOMPAT_RUNTIME_REPORT=log

# Guest audio shield (capability-gated, additive): a port whose APK bundles the
# Android OpenAL-soft reads the HOST's /etc/openal/alsoft.conf too. A CFW that
# ships a native `drivers=` line there (AmberELEC ships drivers=alsa) leaves the
# embedded OpenAL with no matching backend -> the game goes SILENT with no error
# (field case: Tightrope on AmberELEC/P4ELEC; reproduced and fix-proven live on
# dArkOSRE by planting that exact file). Pinning ALSOFT_DRIVERS to the OpenSL
# bridge the loader provides neutralizes only that lethal option. Every port
# without the capability keeps a byte-identical environment.
for NXBOOTSTRAP_CAP in $NXCOMPAT_REQUIRED_CAPABILITIES; do
  [ "$NXBOOTSTRAP_CAP" = audio.embedded-openal ] || continue
  export ALSOFT_DRIVERS=opensl
  echo "AUDIO GUEST: ALSOFT_DRIVERS=opensl pinned (embedded OpenAL; host alsoft.conf neutralized)"
  break
done
unset NXBOOTSTRAP_CAP
# One-line receipt of the inherited audio-relevant environment: when a device
# mutes a guest, this line names the suspects without a second round-trip.
echo "ENV RECEIPT: sdl_audiodriver=${SDL_AUDIODRIVER:-} alsoft_drivers=${ALSOFT_DRIVERS:-} alsoft_conf=${ALSOFT_CONF:-} pulse_server=${PULSE_SERVER:-} xdg_runtime_dir=${XDG_RUNTIME_DIR:-}"

game_pid=
NXBOOTSTRAP_CHILD_STARTTIME=
NXBOOTSTRAP_SHUTDOWN_REQUESTED=0
NXBOOTSTRAP_TERM_SENT=0
NXBOOTSTRAP_SIGNAL_COUNT=0
nxbootstrap_capture_child_starttime() {
  local child_stat child_rest
  case "$game_pid" in ''|*[!0-9]*) return 1 ;; esac
  IFS= read -r child_stat < "/proc/$game_pid/stat" 2>/dev/null || return 1
  child_rest=${child_stat##*) }
  set -- $child_rest
  [ "$#" -ge 20 ] || return 1
  NXBOOTSTRAP_CHILD_STARTTIME=${20}
}
nxbootstrap_child_alive() {
  local child_stat child_rest child_state child_start
  case "$game_pid" in ''|*[!0-9]*) return 1 ;; esac
  [ -n "$NXBOOTSTRAP_CHILD_STARTTIME" ] || return 1
  builtin kill -0 "$game_pid" 2>/dev/null || return 1
  IFS= read -r child_stat < "/proc/$game_pid/stat" 2>/dev/null || return 1
  child_rest=${child_stat##*) }
  set -- $child_rest
  [ "$#" -ge 20 ] || return 1
  child_state=$1
  child_start=${20}
  case "$child_state" in Z|X) return 1 ;; esac
  [ "$child_start" = "$NXBOOTSTRAP_CHILD_STARTTIME" ]
}
nxbootstrap_signal_child() {
  [ "$NXBOOTSTRAP_TERM_SENT" = 0 ] || return 0
  [ -n "$NXBOOTSTRAP_CHILD_STARTTIME" ] || \
    nxbootstrap_capture_child_starttime || return 0
  nxbootstrap_child_alive || return 0
  NXBOOTSTRAP_TERM_SENT=1
  builtin kill -TERM "$game_pid" 2>/dev/null || true
}
nxbootstrap_kill_child_exact() {
  # Re-read state/starttime immediately before KILL. The original child is not
  # replaceable while unreaped, but this also closes every future call site.
  nxbootstrap_child_alive || return 1
  builtin kill -KILL "$game_pid" 2>/dev/null || true
}
nxbootstrap_request_shutdown() {
  NXBOOTSTRAP_SIGNAL_COUNT=$((NXBOOTSTRAP_SIGNAL_COUNT + 1))
  if [ "$NXBOOTSTRAP_SHUTDOWN_REQUESTED" = 0 ]; then
    NXBOOTSTRAP_SHUTDOWN_REQUESTED=1
    # Match the historical wait/grace contract: after the first frontend
    # signal owns termination, later HUP/INT/TERM cannot interrupt the bounded
    # grace period or manufacture another synthetic wait status.
    trap '' INT TERM HUP
  fi
  nxbootstrap_signal_child || true
}
# Read the producer's final inode through an fd, then bind owner, mode, link
# count and the exact health tuple before trusting a verdict. stdout/audio/PID
# lifetime are deliberately irrelevant: only this file can stop a black run.
NXBOOTSTRAP_VIDEO_VERDICT=""
NXBOOTSTRAP_VIDEO_REASON=""
NXBOOTSTRAP_VIDEO_OK_SEEN=0
NXBOOTSTRAP_VIDEO_FATAL=0
NXBOOTSTRAP_VIDEO_FATAL_STATUS=72
nxbootstrap_video_receipt_read() {
  local line extra video_meta video_mode video_links video_owner expected
  NXBOOTSTRAP_VIDEO_VERDICT=""
  NXBOOTSTRAP_VIDEO_REASON=""
  [ -n "${NXBOOTSTRAP_VIDEO_FILE:-}" ] || return 1
  [ -f "$NXBOOTSTRAP_VIDEO_FILE" ] && [ ! -L "$NXBOOTSTRAP_VIDEO_FILE" ] && \
    [ -O "$NXBOOTSTRAP_VIDEO_FILE" ] || return 1
  { exec 8<"$NXBOOTSTRAP_VIDEO_FILE"; } 2>/dev/null || return 1
  video_meta=()
  IFS=' ' read -r -a video_meta \
    <<< "$(LC_ALL=C command ls -Lldn /proc/self/fd/8 2>/dev/null)"
  video_mode=${video_meta[0]:-}
  video_links=${video_meta[1]:-}
  video_owner=${video_meta[2]:-}
  if [ "$video_mode" != "-rw-------" ] || [ "$video_links" != 1 ] || \
     [ "$video_owner" != "$EUID" ] || \
     ! [ "$NXBOOTSTRAP_VIDEO_FILE" -ef /proc/self/fd/8 ]; then
    { exec 8<&-; } 2>/dev/null || true
    return 1
  fi
  IFS= read -r line <&8 || {
    { exec 8<&-; } 2>/dev/null || true
    return 1
  }
  if IFS= read -r extra <&8; then
    { exec 8<&-; } 2>/dev/null || true
    return 1
  fi
  { exec 8<&-; } 2>/dev/null || true
  expected="{\"schema\":\"$NXBOOTSTRAP_VIDEO_SCHEMA\",\"schema_version\":$NXBOOTSTRAP_VIDEO_SCHEMA_VERSION,\"run_id\":\"$NXBOOTSTRAP_HEALTH_RUN_ID\",\"generation\":\"$NXBOOTSTRAP_HEALTH_GENERATION\",\"port_id\":\"$NXBOOTSTRAP_HEALTH_PORT_ID\",\"verdict\":\"OK\",\"reason\":\"non-black\"}"
  if [ "$line" = "$expected" ]; then
    NXBOOTSTRAP_VIDEO_VERDICT=OK
    NXBOOTSTRAP_VIDEO_REASON=non-black
    return 0
  fi
  expected="{\"schema\":\"$NXBOOTSTRAP_VIDEO_SCHEMA\",\"schema_version\":$NXBOOTSTRAP_VIDEO_SCHEMA_VERSION,\"run_id\":\"$NXBOOTSTRAP_HEALTH_RUN_ID\",\"generation\":\"$NXBOOTSTRAP_HEALTH_GENERATION\",\"port_id\":\"$NXBOOTSTRAP_HEALTH_PORT_ID\",\"verdict\":\"BLACK\",\"reason\":\"black-streak\"}"
  if [ "$line" = "$expected" ]; then
    NXBOOTSTRAP_VIDEO_VERDICT=BLACK
    NXBOOTSTRAP_VIDEO_REASON=black-streak
    return 0
  fi
  expected="{\"schema\":\"$NXBOOTSTRAP_VIDEO_SCHEMA\",\"schema_version\":$NXBOOTSTRAP_VIDEO_SCHEMA_VERSION,\"run_id\":\"$NXBOOTSTRAP_HEALTH_RUN_ID\",\"generation\":\"$NXBOOTSTRAP_HEALTH_GENERATION\",\"port_id\":\"$NXBOOTSTRAP_HEALTH_PORT_ID\",\"verdict\":\"BLACK\",\"reason\":\"all-black\"}"
  if [ "$line" = "$expected" ]; then
    NXBOOTSTRAP_VIDEO_VERDICT=BLACK
    NXBOOTSTRAP_VIDEO_REASON=all-black
    return 0
  fi
  expected="{\"schema\":\"$NXBOOTSTRAP_VIDEO_SCHEMA\",\"schema_version\":$NXBOOTSTRAP_VIDEO_SCHEMA_VERSION,\"run_id\":\"$NXBOOTSTRAP_HEALTH_RUN_ID\",\"generation\":\"$NXBOOTSTRAP_HEALTH_GENERATION\",\"port_id\":\"$NXBOOTSTRAP_HEALTH_PORT_ID\",\"verdict\":\"DEAD-CONTEXT\",\"reason\":\"dead-context\"}"
  if [ "$line" = "$expected" ]; then
    NXBOOTSTRAP_VIDEO_VERDICT=DEAD-CONTEXT
    NXBOOTSTRAP_VIDEO_REASON=dead-context
    return 0
  fi
  NXBOOTSTRAP_VIDEO_VERDICT=""
  NXBOOTSTRAP_VIDEO_REASON=""
  return 1
}
nxbootstrap_video_receipt_poll() {
  nxbootstrap_video_receipt_read || return 1
  if [ "$NXBOOTSTRAP_VIDEO_VERDICT" = OK ]; then
    if [ "$NXBOOTSTRAP_VIDEO_OK_SEEN" = 0 ]; then
      echo "VIDEO PROOF: run-bound OK reason=$NXBOOTSTRAP_VIDEO_REASON"
      NXBOOTSTRAP_VIDEO_OK_SEEN=1
    fi
    return 1
  fi
  NXBOOTSTRAP_VIDEO_FATAL=1
  nxbootstrap_runtime_event NXR0004 \
    "conclusive video failure verdict=$NXBOOTSTRAP_VIDEO_VERDICT reason=$NXBOOTSTRAP_VIDEO_REASON; terminating exact child"
  return 0
}
trap nxbootstrap_request_shutdown INT TERM HUP
# Close the lock fd IN THE CHILD ONLY (9>&-): the launcher keeps fd 9 and the
# flock for the whole game, but the game — and any detached helper it forks —
# must not inherit the lock, or an orphaned grandchild would hold the port lock
# after the launcher exits and block the next launch.
nxbootstrap_phase_event runtime START lifecycle 6207 || {
  nxbootstrap_finish
  exit 1
}
if [ -n "$BIN_PRELOAD" ]; then
  LD_PRELOAD="$BIN_PRELOAD${LD_PRELOAD:+:$LD_PRELOAD}" $NXBOOTSTRAP_INTERP_PREFIX "$BIN" 9>&- &
else
  $NXBOOTSTRAP_INTERP_PREFIX "$BIN" 9>&- &
fi
game_pid=$!
nxbootstrap_capture_child_starttime || NXBOOTSTRAP_CHILD_STARTTIME=""
[ "$NXBOOTSTRAP_SHUTDOWN_REQUESTED" = 0 ] || nxbootstrap_signal_child
NXBOOTSTRAP_TERMINATION_TICKS=10
# Supervise the exact child while it is alive. A game that keeps rendering
# audio or merely keeps its PID cannot mask a conclusive BLACK/DEAD-CONTEXT.
while nxbootstrap_child_alive; do
  if [ "$NXBOOTSTRAP_VIDEO_FATAL" = 0 ] && nxbootstrap_video_receipt_poll; then
    nxbootstrap_signal_child || true
  fi
  if [ "$NXBOOTSTRAP_VIDEO_FATAL" = 1 ] || \
     [ "$NXBOOTSTRAP_SHUTDOWN_REQUESTED" = 1 ]; then
    nxbootstrap_signal_child || true
    if [ "$NXBOOTSTRAP_TERMINATION_TICKS" -le 0 ]; then
      echo "== termination deadline expired; sending KILL =="
      nxbootstrap_kill_child_exact || true
      break
    fi
    NXBOOTSTRAP_TERMINATION_TICKS=$((NXBOOTSTRAP_TERMINATION_TICKS - 1))
  fi
  sleep 1 || true
done
if wait "$game_pid"; then status=0; else status=$?; fi
# Catch an atomic terminal receipt published immediately before child exit.
if [ "$NXBOOTSTRAP_VIDEO_FATAL" = 0 ]; then
  nxbootstrap_video_receipt_poll || true
fi
if [ "$NXBOOTSTRAP_SHUTDOWN_REQUESTED" = 1 ]; then
  trap '' INT TERM HUP
  NXBOOTSTRAP_SHUTDOWN_TICKS=10
  while [ "$NXBOOTSTRAP_SHUTDOWN_TICKS" -gt 0 ] && nxbootstrap_child_alive; do
    sleep 1 || true
    NXBOOTSTRAP_SHUTDOWN_TICKS=$((NXBOOTSTRAP_SHUTDOWN_TICKS - 1))
  done
  if nxbootstrap_child_alive; then
    echo "== termination deadline expired; sending KILL =="
    nxbootstrap_kill_child_exact || true
  fi
  # Each handled frontend signal can contribute one synthetic 128+n result.
  NXBOOTSTRAP_REWAIT_BUDGET=$NXBOOTSTRAP_SIGNAL_COUNT
  while [ "$NXBOOTSTRAP_REWAIT_BUDGET" -gt 0 ]; do
    case "$status" in 129|130|143) ;; *) break ;; esac
    NXBOOTSTRAP_REWAIT_BUDGET=$((NXBOOTSTRAP_REWAIT_BUDGET - 1))
    if wait "$game_pid" 2>/dev/null; then status=0; else status=$?; fi
  done
else
  # 128+n can also be wait itself being interrupted; recover the child truth.
  while [ "$status" -gt 128 ] && nxbootstrap_child_alive; do
    if wait "$game_pid"; then status=0; else status=$?; fi
  done
fi
if [ "$NXBOOTSTRAP_VIDEO_FATAL" = 1 ]; then
  # Fatal video evidence always outranks a concurrently written ready receipt.
  # Delete it before the generation state machine can observe it.
  rm -f -- "$NXBOOTSTRAP_HEALTH_FILE" 2>/dev/null || true
  status=$NXBOOTSTRAP_VIDEO_FATAL_STATUS
fi
NXBOOTSTRAP_RUNTIME_EXIT_PERSISTED=0
if nxbootstrap_phase_event runtime EXIT lifecycle 6208 "$status"; then
  NXBOOTSTRAP_RUNTIME_EXIT_PERSISTED=1
else
  echo "WARNING: runtime exit boundary could not be persisted"
fi

# V3-ROLLBACK-01: health proof. Only an exact receipt from THIS run and THIS
# generation can promote pending -> active. It is read through an opened fd and
# checked for owner/mode/inode/link-count before its canonical JSON is trusted.
nxbootstrap_health_receipt_valid() {
  local expected line extra health_meta health_mode health_links
  [ -n "${NXBOOTSTRAP_HEALTH_FILE:-}" ] || return 1
  [ "$NXBOOTSTRAP_VIDEO_FATAL" = 0 ] || return 1
  if [ "$NXBOOTSTRAP_VIDEO_REQUIRED" = 1 ]; then
    [ "$NXBOOTSTRAP_VIDEO_OK_SEEN" = 1 ] || return 1
    # OK is not a sticky capability. Re-open and authenticate the current
    # final inode: removal, malformed replacement or a revoked verdict after
    # the observed OK all invalidate health promotion.
    nxbootstrap_video_receipt_read || return 1
    [ "$NXBOOTSTRAP_VIDEO_VERDICT" = OK ] && \
      [ "$NXBOOTSTRAP_VIDEO_REASON" = non-black ] || return 1
  fi
  [ -f "$NXBOOTSTRAP_HEALTH_FILE" ] && [ ! -L "$NXBOOTSTRAP_HEALTH_FILE" ] && \
    [ -O "$NXBOOTSTRAP_HEALTH_FILE" ] || return 1
  { exec 8<"$NXBOOTSTRAP_HEALTH_FILE"; } 2>/dev/null || return 1
  health_meta=()
  IFS=' ' read -r -a health_meta \
    <<< "$(LC_ALL=C command ls -Lldn /proc/self/fd/8 2>/dev/null)"
  health_mode=${health_meta[0]:-}
  health_links=${health_meta[1]:-}
  if [ "$health_mode" != "-rw-------" ] || [ "$health_links" != 1 ] || \
     ! [ "$NXBOOTSTRAP_HEALTH_FILE" -ef /proc/self/fd/8 ]; then
    { exec 8<&-; } 2>/dev/null || true
    return 1
  fi
  IFS= read -r line <&8 || {
    { exec 8<&-; } 2>/dev/null || true
    return 1
  }
  if IFS= read -r extra <&8; then
    { exec 8<&-; } 2>/dev/null || true
    return 1
  fi
  { exec 8<&-; } 2>/dev/null || true
  expected="{\"schema\":\"$NXBOOTSTRAP_HEALTH_SCHEMA\",\"schema_version\":$NXBOOTSTRAP_HEALTH_SCHEMA_VERSION,\"run_id\":\"$NXBOOTSTRAP_HEALTH_RUN_ID\",\"generation\":\"$NXBOOTSTRAP_HEALTH_GENERATION\",\"port_id\":\"$NXBOOTSTRAP_HEALTH_PORT_ID\",\"status\":\"ready\"}"
  [ "$line" = "$expected" ]
}
nxbootstrap_clean_exit_health_valid() {
  # Compatibility safety net for a FIRST generation and for an already-active
  # stable generation. The child status comes from wait(2) on the exact tracked
  # PID and must also have reached the durable run-bound EXIT boundary. This is
  # deliberately NOT enough to promote an update while an older healthy
  # rollback anchor exists: that path still requires the exact adapter receipt.
  [ "${NXBOOTSTRAP_RUNTIME_EXIT_PERSISTED:-0}" = 1 ] || return 1
  [ "$status" -eq 0 ] 2>/dev/null || return 1
  [ "$NXBOOTSTRAP_VIDEO_FATAL" = 0 ] || return 1
  if [ "$NXBOOTSTRAP_VIDEO_REQUIRED" = 1 ]; then
    [ "$NXBOOTSTRAP_VIDEO_OK_SEEN" = 1 ] || return 1
    nxbootstrap_video_receipt_read || return 1
    [ "$NXBOOTSTRAP_VIDEO_VERDICT" = OK ] && \
      [ "$NXBOOTSTRAP_VIDEO_REASON" = non-black ] || return 1
  fi
  return 0
}
if [ -n "${NXBOOTSTRAP_SELECTED_GENERATION:-}" ]; then
  nxbootstrap_state_active=$(nxbootstrap_state_field active)
  nxbootstrap_state_pending=$(nxbootstrap_state_field pending)
  nxbootstrap_state_previous=$(nxbootstrap_state_field previous_healthy)
  nxbootstrap_state_seq=$(nxbootstrap_state_field activation_seq)
  nxbootstrap_state_failures=$(nxbootstrap_state_field prehealth_failures)
  nxbootstrap_state_last_health_run=$(nxbootstrap_state_field last_health_run_id)
  case "$nxbootstrap_state_seq" in ''|*[!0-9]*) nxbootstrap_state_seq=0 ;; esac
  case "$nxbootstrap_state_failures" in ''|*[!0-9]*) nxbootstrap_state_failures=0 ;; esac
  nxbootstrap_generation_id_valid "$nxbootstrap_state_active" || nxbootstrap_state_active=null
  nxbootstrap_generation_id_valid "$nxbootstrap_state_pending" || nxbootstrap_state_pending=null
  nxbootstrap_generation_id_valid "$nxbootstrap_state_previous" || nxbootstrap_state_previous=null
  NXBOOTSTRAP_HEALTH_VALID_SEEN=0
  NXBOOTSTRAP_HEALTH_AUTHORITY=none
  if nxbootstrap_health_receipt_valid; then
    NXBOOTSTRAP_HEALTH_VALID_SEEN=1
    NXBOOTSTRAP_HEALTH_AUTHORITY=adapter-receipt
  elif nxbootstrap_clean_exit_health_valid && \
       { { [ "$nxbootstrap_state_pending" = "$NXBOOTSTRAP_SELECTED_GENERATION" ] && \
             [ "$nxbootstrap_state_active" = null ] && \
             [ "$nxbootstrap_state_previous" = null ]; } || \
         { [ "$nxbootstrap_state_pending" != "$NXBOOTSTRAP_SELECTED_GENERATION" ] && \
             [ "$nxbootstrap_state_active" = "$NXBOOTSTRAP_SELECTED_GENERATION" ]; }; }; then
    NXBOOTSTRAP_HEALTH_VALID_SEEN=1
    NXBOOTSTRAP_HEALTH_AUTHORITY=clean-exit
  fi
  if [ "$NXBOOTSTRAP_HEALTH_VALID_SEEN" = 1 ]; then
    if [ "$nxbootstrap_state_pending" = "$NXBOOTSTRAP_SELECTED_GENERATION" ]; then
      # The formerly active generation becomes the rollback anchor only now,
      # when the new generation has actually proved healthy.
      if [ "$nxbootstrap_state_active" != null ] && \
         nxbootstrap_generation_complete "$NXRUNTIME_DIR/generations/$nxbootstrap_state_active"; then
        if nxbootstrap_generation_is_v2 "$NXRUNTIME_DIR/generations/$NXBOOTSTRAP_SELECTED_GENERATION"; then
          if nxbootstrap_generation_is_v2 "$NXRUNTIME_DIR/generations/$nxbootstrap_state_active"; then
            nxbootstrap_state_previous=$nxbootstrap_state_active
          else
            nxbootstrap_state_previous=null
          fi
        else
          nxbootstrap_state_previous=$nxbootstrap_state_active
        fi
      fi
      nxbootstrap_state_active=$NXBOOTSTRAP_SELECTED_GENERATION
      nxbootstrap_state_pending=null
    fi
    if nxbootstrap_write_state "$NXBOOTSTRAP_SELECTED_GENERATION" \
      "${nxbootstrap_state_pending:-null}" \
      "${nxbootstrap_state_previous:-null}" "$nxbootstrap_state_seq" 0 \
      "null" "$NXOBS_RUN_ID"; then
      if [ "$NXBOOTSTRAP_HEALTH_AUTHORITY" = adapter-receipt ]; then
        nxbootstrap_update_event NXU0006 "generation $NXBOOTSTRAP_SELECTED_GENERATION proved healthy receipt_run=$NXOBS_RUN_ID"
      else
        nxbootstrap_update_event NXU0006 "generation $NXBOOTSTRAP_SELECTED_GENERATION proved healthy clean_exit_run=$NXOBS_RUN_ID"
      fi
    else
      nxbootstrap_update_event NXU0011 "valid health receipt observed but active state was not persisted; generation remains unpromoted"
      status=70
    fi
  elif [ "$nxbootstrap_state_pending" = "$NXBOOTSTRAP_SELECTED_GENERATION" ]; then
    nxbootstrap_state_failures=$((nxbootstrap_state_failures + 1))
    if nxbootstrap_write_state "${nxbootstrap_state_active:-null}" \
      "$nxbootstrap_state_pending" "${nxbootstrap_state_previous:-null}" \
      "$nxbootstrap_state_seq" "$nxbootstrap_state_failures" \
      "$NXBOOTSTRAP_SELECTED_GENERATION" \
      "${nxbootstrap_state_last_health_run:-null}"; then
      nxbootstrap_update_event NXU0005 "no valid run-bound health receipt for pending generation $NXBOOTSTRAP_SELECTED_GENERATION; prehealth_failures=$nxbootstrap_state_failures"
    else
      nxbootstrap_update_event NXU0011 "prehealth failure count could not be persisted; promotion remains closed"
      status=70
    fi
  else
    nxbootstrap_update_event NXU0007 "stable generation $NXBOOTSTRAP_SELECTED_GENERATION produced no valid health receipt; active state unchanged"
  fi
  # V4-BOOT-01: a run that skipped the deep validation and then could not
  # prove health may be sitting on corrupted live bytes.  Arm a one-shot
  # marker so the NEXT boot takes the deep verification/heal path; a healthy
  # run never creates it and a completed deep pass removes it.
  if [ "${NXBOOTSTRAP_FAST_BOOT:-0}" = 1 ] && \
     [ "${NXBOOTSTRAP_HEALTH_VALID_SEEN:-0}" != 1 ]; then
    ( umask 077; : > "$NXRUNTIME_DIR/deep-verify-next" ) 2>/dev/null || true
  fi
  rm -f -- "$NXBOOTSTRAP_HEALTH_FILE" 2>/dev/null || true
fi

# RUNTIME DIAGNOSIS: turn a bare exit code + black screen into one readable
# verdict in the log. Signatures are read from this same log; a clean exit or a
# frontend chord (SIGTERM/SIGKILL) is NOT an error. Never alters $status.
NXBOOTSTRAP_LOG="$GAMEDIR/log.txt"
nxbootstrap_log_has() { [ -r "$NXBOOTSTRAP_LOG" ] && LC_ALL=C grep -qaE "$1" "$NXBOOTSTRAP_LOG" 2>/dev/null; }
NXBOOTSTRAP_DIAG="unclassified — see the log above"
if nxbootstrap_log_has 'undefined symbol:'; then
  NXBOOTSTRAP_DIAG="undefined-symbol — the loader needs a symbol the device library does not export; rebuild against the device SDK ($(LC_ALL=C grep -aoE 'undefined symbol: [A-Za-z0-9_]+' "$NXBOOTSTRAP_LOG" 2>/dev/null | head -n1))"
elif nxbootstrap_log_has 'cannot open shared object'; then
  NXBOOTSTRAP_DIAG="missing-library — a required .so is absent on this CFW; bundle it in the port ($(LC_ALL=C grep -aoE '[A-Za-z0-9._+-]+\.so[A-Za-z0-9._]*: cannot open shared object' "$NXBOOTSTRAP_LOG" 2>/dev/null | head -n1))"
elif [ "$status" = 127 ]; then
  NXBOOTSTRAP_DIAG="status-127 — the executable or its dynamic loader could not be run (missing interpreter/library)"
elif [ "$status" = 139 ]; then
  NXBOOTSTRAP_DIAG="crash-SIGSEGV — the game hit a segfault; read the last frames above for the failing call"
elif [ "$status" = 134 ]; then
  NXBOOTSTRAP_DIAG="crash-SIGABRT — the game aborted itself (assert/abort); the message above names the reason"
elif [ "$status" = 132 ]; then
  NXBOOTSTRAP_DIAG="crash-SIGILL — illegal instruction, usually a wrong-arch or bad-codegen build"
elif nxbootstrap_log_has 'frame proof verdict=(black|absent)' || \
     { nxbootstrap_log_has 'frame proof' && ! nxbootstrap_log_has 'frame proof verdict=OK'; }; then
  NXBOOTSTRAP_DIAG="black-screen — the process ran but no non-black frame was observed; check EGL/GL context and the video receipt above"
elif [ "$status" = 0 ] || [ "$status" = 143 ] || [ "$status" = 137 ] || [ "$status" = 130 ]; then
  NXBOOTSTRAP_DIAG="clean — exited normally or via the frontend/exit chord (status $status)"
else
  NXBOOTSTRAP_DIAG="nonzero-exit (status $status) — the game returned an error; read the log above"
fi
echo "RUNTIME DIAGNOSIS: $NXBOOTSTRAP_DIAG"
# SUPPORT block: bounded identifiers for the local diagnostic inputs. Raw logs
# remain internal; only nxobs may turn them into a shareable sanitized bundle.
echo "== SUPPORT =="
echo "port=riptidegp1 version=$(LC_ALL=C head -c 32 "$GAMEDIR/version.txt" 2>/dev/null | tr -d "[:space:]") launcher=0.7.6 cfw=${CFW_NAME:-none}"
if [ -r "$GAMEDIR/nxextract-version.txt" ]; then
  echo "nxextract=$(LC_ALL=C head -c 32 "$GAMEDIR/nxextract-version.txt" 2>/dev/null | tr -d '[:space:]')"
fi
LC_ALL=C grep -am1 '"schema":"org.nextos.nxextract.terminal-result"' \
  "$GAMEDIR/log.txt" 2>/dev/null | head -c 2048 || true
echo "support-bundle=share only the sanitized nxobs bundle or its manifest hash; never raw logs"
echo "== end (status $status) =="

# The game may leave the console keymap off (K_OFF); reset before handing back.
[ -n "$CUR_TTY" ] && [ -c "$CUR_TTY" ] && printf '\033c' > "$CUR_TTY" 2>/dev/null
nxbootstrap_finish
exit $status
